import React from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { InAppLink } from '../../router/InAppLink';
import { navigateInAppPath } from '../../router/navigateInAppPath';
import { useNavTitle, useAppToast } from '@linm-soft-org/linm-web-common-components';
import { StatsCard, StatsCardsGrid, Slideout, TableCard } from '../../ui';
import JobsListToolbar from './JobsListToolbar';
import styles from './JobInternalPage.module.css';
import {
  jobsService,
  type ImportRunDetail,
  type JobDirection,
  type PlatformEventDetail,
  type PlatformJobDashboardStats,
} from '../../services/jobs';
import { JobEventTypeFilter } from './components/JobEventTypeFilter';
import { JobEventsTable } from './components/JobEventsTable';
import { JobEventDetailPanel } from './components/JobEventDetailPanel';
import { JobImportRunDetailPanel } from './components/JobImportRunDetailPanel';
import { isEventActive } from './jobStatusDisplay';
import { buildJobsDirectionCardHref, buildJobsEventsHref } from './jobsEventLinks';
import { AdminPermNavLinks } from '../../components/auth/AdminPermNavLinks';

const directionTitles: Record<string, string> = {
  inbound: 'Inbound',
  outbound: 'Outbound',
  internal: 'Internal',
};

const SLIDEOUT_WIDTH = '640px';

const JobDashboardPage: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const path = location.pathname.toLowerCase();
  const direction = (path.includes('/inbound')
    ? 'Inbound'
    : path.includes('/outbound')
      ? 'Outbound'
      : path.includes('/internal')
        ? 'Internal'
        : '') as JobDirection | '';

  const dirKey = path.includes('/inbound') ? 'inbound' : path.includes('/outbound') ? 'outbound' : '';
  useNavTitle(direction ? `Job dashboard — ${directionTitles[dirKey] ?? direction}` : 'Job dashboard');
  const toast = useAppToast();

  const selectedEventId = searchParams.get('eventId');

  const [stats, setStats] = React.useState<PlatformJobDashboardStats[]>([]);
  const [eventTypes, setEventTypes] = React.useState<Awaited<ReturnType<typeof jobsService.getEventTypes>>>([]);
  const [eventType, setEventType] = React.useState('');
  const [status, setStatus] = React.useState('');
  const [events, setEvents] = React.useState<Awaited<ReturnType<typeof jobsService.getEvents>>['items']>([]);
  const [eventsTotal, setEventsTotal] = React.useState(0);
  const [loading, setLoading] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState('');
  const [searchApplied, setSearchApplied] = React.useState('');
  const [eventDetail, setEventDetail] = React.useState<PlatformEventDetail | null>(null);
  const [loadingDetail, setLoadingDetail] = React.useState(false);
  const [linkedRunId, setLinkedRunId] = React.useState<string | null>(null);
  const [linkedRunDetail, setLinkedRunDetail] = React.useState<ImportRunDetail | null>(null);
  const [loadingLinkedRun, setLoadingLinkedRun] = React.useState(false);
  const detailReqRef = React.useRef(0);

  const basePath = location.pathname.replace(/\/$/, '') || location.pathname;

  const buildHref = React.useCallback(
    (eventId: string | null) => {
      const sp = new URLSearchParams();
      if (eventId) sp.set('eventId', eventId);
      const q = sp.toString();
      return q ? `${basePath}?${q}` : basePath;
    },
    [basePath],
  );

  React.useEffect(() => {
    const timer = window.setTimeout(() => {
      const next = searchQuery.trim();
      if (next === searchApplied) return;
      setSearchApplied(next);
    }, 400);
    return () => window.clearTimeout(timer);
  }, [searchQuery, searchApplied]);

  const load = React.useCallback(() => {
    setLoading(true);
    const t = setTimeout(() => {
      Promise.all([
        jobsService.getDashboard({ direction: direction || undefined, eventType: eventType || undefined }),
        jobsService.getEventTypes(direction || undefined),
        jobsService.getEvents({
          page: 1,
          pageSize: 25,
          direction: direction || undefined,
          eventType: eventType || undefined,
          jobStatus: status || undefined,
          search: searchApplied || undefined,
        }),
      ])
        .then(([dash, types, ev]) => {
          setStats(dash);
          setEventTypes(types);
          setEvents(ev.items);
          setEventsTotal(ev.total);
        })
        .catch((e: Error) => toast.error(e.message))
        .finally(() => setLoading(false));
    }, 0);
    return () => clearTimeout(t);
  }, [direction, eventType, status, searchApplied, toast]);

  React.useEffect(() => load(), [load]);

  const loadDetail = React.useCallback(
    (eventId: string) => {
      const req = ++detailReqRef.current;
      setLoadingDetail(true);
      return jobsService
        .getEvent(eventId)
        .then((detail) => {
          if (req !== detailReqRef.current) return;
          if (detail.eventId !== eventId) return;
          setEventDetail(detail);
        })
        .catch((e: Error) => {
          if (req !== detailReqRef.current) return;
          toast.error(e.message);
          setEventDetail(null);
        })
        .finally(() => {
          if (req !== detailReqRef.current) return;
          setLoadingDetail(false);
        });
    },
    [toast],
  );

  const selectedEvent = events.find((e) => e.eventId === selectedEventId);
  const selectedIsActive = selectedEvent ? isEventActive(selectedEvent) : false;
  const detailMatchesSelection =
    Boolean(selectedEventId) && eventDetail?.eventId === selectedEventId;
  const hasProcessing = events.some((e) => e.processingStatus === 'Processing');
  const hasActiveListItems = events.some((e) => isEventActive(e));

  React.useEffect(() => {
    if (!hasProcessing && !hasActiveListItems) return undefined;
    const t = setInterval(() => load(), 4000);
    return () => clearInterval(t);
  }, [hasProcessing, hasActiveListItems, load]);

  React.useEffect(() => {
    if (!selectedEventId) {
      detailReqRef.current += 1;
      setEventDetail(null);
      setLoadingDetail(false);
      return undefined;
    }
    setEventDetail((prev) => (prev?.eventId === selectedEventId ? prev : null));
    loadDetail(selectedEventId);
    if (!selectedIsActive) return undefined;
    const t = setInterval(() => {
      loadDetail(selectedEventId);
      load();
    }, 4000);
    return () => clearInterval(t);
  }, [selectedEventId, selectedIsActive, loadDetail, load]);

  const handleSelectEvent = (eventId: string) => {
    if (eventId === selectedEventId) return;
    navigateInAppPath(buildHref(eventId), navigate);
  };

  const closeEventDetail = () => {
    navigateInAppPath(buildHref(null), navigate, { replace: true });
  };

  const openImportRunSlideout = React.useCallback(
    (runId: string) => {
      setLinkedRunId(runId);
      setLoadingLinkedRun(true);
      jobsService
        .getImportRun(runId)
        .then(setLinkedRunDetail)
        .catch((e: Error) => {
          toast.error(e.message);
          setLinkedRunDetail(null);
        })
        .finally(() => setLoadingLinkedRun(false));
    },
    [toast],
  );

  const closeLinkedRunSlideout = React.useCallback(() => {
    setLinkedRunId(null);
    setLinkedRunDetail(null);
  }, []);

  const primary = React.useMemo(() => {
    if (direction) {
      return stats.find((s) => s.direction === direction) ?? stats[0];
    }
    const active = stats.filter((s) => !s.isPlaceholder);
    if (active.length === 0) return stats[0];
    return {
      direction: 'All',
      isPlaceholder: false,
      total: active.reduce((n, s) => n + s.total, 0),
      completed: active.reduce((n, s) => n + s.completed, 0),
      failed: active.reduce((n, s) => n + s.failed, 0),
      retryPending: active.reduce((n, s) => n + s.retryPending, 0),
      processing: active.reduce((n, s) => n + s.processing, 0),
      pending: active.reduce((n, s) => n + s.pending, 0),
      deadLetter: active.reduce((n, s) => n + s.deadLetter, 0),
    };
  }, [direction, stats]);

  const eventsScopeDirection = direction || undefined;

  const goEvents = React.useCallback(
    (jobStatus?: string) => {
      navigateInAppPath(
        buildJobsEventsHref({
          direction: eventsScopeDirection,
          jobStatus,
          search: searchApplied || undefined,
        }),
        navigate,
      );
    },
    [navigate, eventsScopeDirection, searchApplied],
  );

  return (
    <div data-testid="job-dashboard-page">
      <AdminPermNavLinks
        data-testid="job-dashboard-perm-nav"
        style={{ marginBottom: 12 }}
        items={[
          { to: '/admin/jobs', label: '← Job monitoring', permissionCode: 'admin:jobs:hub:read' },
          { to: '/admin/jobs/schedule', label: 'Cấu hình lịch', permissionCode: 'admin:jobs:schedule:read' },
          { to: '/admin/jobs/external-sync', label: 'Cấu hình sync REVA', permissionCode: 'admin:jobs:external-sync:read' },
          { to: '/admin/jobs/external-runs', label: 'Theo dõi sync ngoài', permissionCode: 'admin:jobs:external-runs:read' },
          { to: '/admin/jobs/pos-inbound-runs', label: 'POS inbound runs', permissionCode: 'admin:jobs:pos-inbound-runs:read' },
          { to: '/admin/jobs/internal', label: 'Job nội bộ', permissionCode: 'admin:jobs:internal:read' },
        ]}
      />

      <JobEventTypeFilter
        eventTypes={eventTypes}
        eventType={eventType}
        onEventTypeChange={setEventType}
        status={status}
        onStatusChange={setStatus}
      />

      {primary?.isPlaceholder ? (
        <p style={{ color: '#666', marginBottom: 16 }}>
          {'placeholderMessage' in primary ? primary.placeholderMessage : null}
        </p>
      ) : null}

      {primary && !primary.isPlaceholder ? (
        <StatsCardsGrid>
          <StatsCard
            label="Tổng"
            value={primary.total}
            variant="total"
            loading={loading}
            onClick={() => goEvents()}
          />
          <StatsCard
            label="Pass (Completed)"
            value={primary.completed}
            variant="success"
            loading={loading}
            onClick={() => goEvents('Completed')}
          />
          <StatsCard
            label="Fail"
            value={primary.failed}
            variant="danger"
            loading={loading}
            onClick={() => goEvents('Failed')}
          />
          <StatsCard
            label="Retry pending"
            value={primary.retryPending}
            variant="warning"
            loading={loading}
            onClick={() => goEvents('RetryPending')}
          />
          <StatsCard
            label="Processing"
            value={primary.processing}
            variant="warning"
            loading={loading}
            onClick={() => goEvents('Processing')}
          />
        </StatsCardsGrid>
      ) : null}

      {!direction && stats.length > 0 ? (
        <div style={{ marginTop: 24 }}>
          <h3>Theo hướng</h3>
          <StatsCardsGrid>
            {stats.map((s) => (
              <StatsCard
                key={s.direction}
                label={s.direction}
                value={s.isPlaceholder ? '—' : s.total}
                variant="total"
                loading={loading}
                onClick={
                  s.isPlaceholder
                    ? undefined
                    : () => navigateInAppPath(buildJobsDirectionCardHref(s.direction), navigate)
                }
              />
            ))}
          </StatsCardsGrid>
        </div>
      ) : null}

      <div className={`${styles.shell} ${styles.shellBelowStats}`}>
        <TableCard
          listShell
          header={
            <div>
              <h4 className={styles.listHeaderTitle}>
                Event gần đây{' '}
                <InAppLink
                  to={buildJobsEventsHref({
                    direction: eventsScopeDirection,
                    search: searchApplied || undefined,
                  })}
                  style={{ fontSize: 14, fontWeight: 400 }}
                >
                  Xem tất cả →
                </InAppLink>
              </h4>
              <p className={styles.listHint}>
                Click dòng để xem chi tiết job. Tìm theo eventId, sourceId, documentKey, connector, lỗi, PayloadJson (BE).
              </p>
              <JobsListToolbar
                searchQuery={searchQuery}
                onSearchChange={setSearchQuery}
                searchPlaceholder="Tìm eventId, sourceId, documentKey, connector, lỗi, JSON…"
                searchTestId="job-dashboard-events-search"
                onRefresh={load}
                refreshDisabled={loading}
                totalCount={eventsTotal}
                filteredCount={events.length}
                loading={loading}
                itemLabel="event"
              />
            </div>
          }
        >
          <div className={styles.eventsTableWrap}>
            {loading && events.length === 0 ? (
              <p className={styles.gridLoading}>Đang tải…</p>
            ) : events.length === 0 ? (
              <p className={styles.gridEmpty}>
                {searchApplied ? 'Không tìm thấy event phù hợp.' : 'Không có event'}
              </p>
            ) : (
              <JobEventsTable
                events={events}
                selectedEventId={selectedEventId}
                eventHref={(eventId) => buildHref(eventId)}
                onSelectEvent={handleSelectEvent}
              />
            )}
          </div>
        </TableCard>
      </div>

      <Slideout
        isOpen={Boolean(selectedEventId)}
        onClose={closeEventDetail}
        title="Chi tiết job / event"
        width={SLIDEOUT_WIDTH}
        data-testid="job-dashboard-event-detail-slideout"
        customFooter={
          <button type="button" className={styles.closeBtn} onClick={closeEventDetail}>
            Đóng
          </button>
        }
      >
        <div className={styles.slideoutBody}>
          {!selectedEventId ? (
            <p style={{ color: '#64748b' }}>Chọn một dòng để xem chi tiết.</p>
          ) : loadingDetail && !detailMatchesSelection ? (
            <p>Đang tải…</p>
          ) : detailMatchesSelection && eventDetail ? (
            <JobEventDetailPanel
              detail={eventDetail}
              onOpenImportRun={openImportRunSlideout}
              onRequeued={() => {
                load();
                if (selectedEventId) loadDetail(selectedEventId);
              }}
            />
          ) : (
            <p style={{ color: '#64748b' }}>Không tải được chi tiết.</p>
          )}
        </div>
      </Slideout>

      <Slideout
        isOpen={Boolean(linkedRunId)}
        onClose={closeLinkedRunSlideout}
        title="Chi tiết / tiến độ import"
        width={SLIDEOUT_WIDTH}
        data-testid="job-dashboard-linked-import-slideout"
        customFooter={
          <button type="button" className={styles.closeBtn} onClick={closeLinkedRunSlideout}>
            Đóng
          </button>
        }
      >
        <div className={styles.slideoutBody}>
          <JobImportRunDetailPanel
            runDetail={linkedRunDetail}
            loading={loadingLinkedRun}
            showEventsLink={false}
          />
        </div>
      </Slideout>
    </div>
  );
};

export default JobDashboardPage;
