/** Calendar-month split for Admin Resync — 01/01–31/12 → 12 ranges. */

export const MONTH_SPLIT_MODE_SEQUENTIAL = 'sequential' as const;

export type MonthSplitMode = typeof MONTH_SPLIT_MODE_SEQUENTIAL;

export type MonthSlice = {
  fromDate: string;
  toDate: string;
  year: number;
  month: number;
  label: string;
};

export type MonthSplitChain = {
  connectorKey: string;
  currentRunId: string;
  currentSlice: MonthSlice;
  remaining: MonthSlice[];
  completed: MonthSlice[];
  total: number;
  startedAt: string;
  syncMode?: 'refill' | 'resync';
};

export const MONTH_SPLIT_STORAGE_KEY = 'linm.admin.externalSync.monthSplitChain';
export const MONTH_SPLIT_CHAIN_EVENT = 'linm-admin-month-split-chain';

const YMD = /^(\d{4})-(\d{2})-(\d{2})$/;

export function isRevaFmVoucherConnector(configKey: string): boolean {
  const key = configKey.trim().toLowerCase();
  if (!key.startsWith('reva-fm-')) return false;
  return key !== 'reva-materials' && key !== 'reva-customers';
}

function parseYmd(value: string): { y: number; m: number; d: number } | null {
  const match = YMD.exec(value.trim());
  if (!match) return null;
  const y = Number(match[1]);
  const m = Number(match[2]);
  const d = Number(match[3]);
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;
  return { y, m, d };
}

function ymd(y: number, m: number, d: number): string {
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

export function lastDayOfMonth(year: number, month: number): number {
  return new Date(Date.UTC(year, month, 0)).getUTCDate();
}

function sliceLabel(year: number, month: number, startDay: number, endDay: number): string {
  const mm = String(month).padStart(2, '0');
  const full = startDay === 1 && endDay === lastDayOfMonth(year, month);
  if (full) return `${mm}/${year}`;
  return `${String(startDay).padStart(2, '0')}/${mm}–${String(endDay).padStart(2, '0')}/${mm}/${year}`;
}

/** Clip each calendar month to from..to (tháng dở giữ đúng đầu/cuối range). */
export function splitDateRangeByMonth(fromDate: string, toDate: string): MonthSlice[] {
  const from = parseYmd(fromDate);
  const to = parseYmd(toDate);
  if (!from || !to) return [];
  if (fromDate > toDate) return [];

  const slices: MonthSlice[] = [];
  let y = from.y;
  let m = from.m;
  while (y < to.y || (y === to.y && m <= to.m)) {
    const startDay = y === from.y && m === from.m ? from.d : 1;
    const endDay = y === to.y && m === to.m ? to.d : lastDayOfMonth(y, m);
    slices.push({
      fromDate: ymd(y, m, startDay),
      toDate: ymd(y, m, endDay),
      year: y,
      month: m,
      label: sliceLabel(y, m, startDay, endDay),
    });
    m += 1;
    if (m > 12) {
      m = 1;
      y += 1;
    }
  }
  return slices;
}

export function formatMonthSplitPreview(slices: MonthSlice[]): string {
  if (slices.length === 0) return '';
  if (slices.length === 1) return `Sẽ tạo 1 run: ${slices[0].label}`;
  const labels = slices.map((s) => s.label);
  if (labels.length <= 12) {
    return `Sẽ tạo ${slices.length} run: ${labels.join(' · ')}`;
  }
  return `Sẽ tạo ${slices.length} run: ${labels.slice(0, 3).join(' · ')} · … · ${labels[labels.length - 1]}`;
}

export function isMonthSplitAbortStatus(status: string): boolean {
  const s = status.trim();
  return s === 'Failed' || s === 'Cancelled' || s === 'Canceled' || s === 'Stopped';
}

export function isMonthSplitContinueStatus(status: string): boolean {
  const s = status.trim();
  return s === 'Success' || s === 'Partial' || s === 'Skipped' || s === 'Completed' || s === 'Done';
}

function isChain(value: unknown): value is MonthSplitChain {
  if (!value || typeof value !== 'object') return false;
  const c = value as MonthSplitChain;
  return Boolean(c.connectorKey && c.currentRunId && c.currentSlice);
}

function readChainMap(): Record<string, MonthSplitChain> {
  if (typeof sessionStorage === 'undefined') return {};
  try {
    const raw = sessionStorage.getItem(MONTH_SPLIT_STORAGE_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as MonthSplitChain | Record<string, MonthSplitChain>;
    if (isChain(parsed)) return { [parsed.connectorKey]: parsed };
    if (!parsed || typeof parsed !== 'object') return {};
    const map: Record<string, MonthSplitChain> = {};
    for (const [key, value] of Object.entries(parsed)) {
      if (isChain(value)) map[value.connectorKey || key] = value;
    }
    return map;
  } catch {
    return {};
  }
}

function persistChainMap(map: Record<string, MonthSplitChain>): void {
  if (typeof sessionStorage === 'undefined') return;
  if (Object.keys(map).length === 0) sessionStorage.removeItem(MONTH_SPLIT_STORAGE_KEY);
  else sessionStorage.setItem(MONTH_SPLIT_STORAGE_KEY, JSON.stringify(map));
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new Event(MONTH_SPLIT_CHAIN_EVENT));
  }
}

/** Mọi chuỗi đang mở (1 connector = 1 chuỗi). */
export function readAllMonthSplitChains(): MonthSplitChain[] {
  return Object.values(readChainMap());
}

/** Không truyền key → chuỗi đầu (tương thích chỗ chỉ cần 1). */
export function readMonthSplitChain(connectorKey?: string): MonthSplitChain | null {
  const map = readChainMap();
  if (connectorKey?.trim()) return map[connectorKey.trim()] ?? null;
  return Object.values(map)[0] ?? null;
}

export function findMonthSplitChainByRunId(runId: string): MonthSplitChain | null {
  if (!runId) return null;
  return readAllMonthSplitChains().find((c) => c.currentRunId === runId) ?? null;
}

/** `null` + key → xóa 1 connector. `null` không key → xóa hết. */
export function writeMonthSplitChain(chain: MonthSplitChain | null, connectorKey?: string): void {
  const map = readChainMap();
  if (!chain) {
    const key = connectorKey?.trim();
    if (key) delete map[key];
    else {
      persistChainMap({});
      return;
    }
    persistChainMap(map);
    return;
  }
  map[chain.connectorKey] = chain;
  persistChainMap(map);
}

export function subscribeMonthSplitChain(onChange: () => void): () => void {
  if (typeof window === 'undefined') return () => undefined;
  const handler = () => onChange();
  window.addEventListener(MONTH_SPLIT_CHAIN_EVENT, handler);
  window.addEventListener('storage', handler);
  return () => {
    window.removeEventListener(MONTH_SPLIT_CHAIN_EVENT, handler);
    window.removeEventListener('storage', handler);
  };
}
