import React from 'react';
import ExternalSyncRunsSplitPane from './components/ExternalSyncRunsSplitPane';
import ExternalSyncVatRefillPanel from './views/ExternalSyncVatRefillPanel';

const VatRefillRunsPage: React.FC = () => {
  const splitPaneRef = React.useRef<{ openRunAndScroll: (runId: string) => void }>(null);

  const handleRunStarted = React.useCallback((runId: string) => {
    splitPaneRef.current?.openRunAndScroll(runId);
  }, []);

  return (
    <ExternalSyncRunsSplitPane
      ref={splitPaneRef}
      view="vat-refill"
      title="Re-fill VAT HĐ POS"
    >
      <ExternalSyncVatRefillPanel onRunStarted={handleRunStarted} />
    </ExternalSyncRunsSplitPane>
  );
};

export default VatRefillRunsPage;
