import React from 'react';
import { Provider } from 'react-redux';
import {
  AlertProvider,
  ReduxToastContainer,
  ToastProvider,
} from '@linm-soft-org/linm-web-common-components';
import { store } from '../store/store';

/** Redux + alert/toast for org catalog parcels mounted from Home (context does not cross SystemJS). */
export const OrgCatalogParcelShell: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <Provider store={store}>
    <AlertProvider>
      <ToastProvider>
        <ReduxToastContainer />
        {children}
      </ToastProvider>
    </AlertProvider>
  </Provider>
);
