import { medicalOrgRequest } from './client';
import { isRmmsOrgCatalog, toRmmsOrgUnitWrite } from './rmmsOrgCatalog';

export interface MedicalDepartment {
  id: string;
  name: string;
  code?: string | null;
  description?: string | null;
  isActive: boolean;
  sortOrder: number;
  createdAt?: string;
  updatedAt?: string;
  createdByName?: string;
  kind?: string;
  parentCode?: string | null;
}

export interface DepartmentPaged {
  items: MedicalDepartment[];
  page: number;
  pageSize: number;
  totalCount: number;
}

export interface DepartmentStats {
  total: number;
  active: number;
  inactive: number;
}

export interface DepartmentWriteRequest {
  name: string;
  code?: string | null;
  description?: string | null;
  isActive: boolean;
  sortOrder: number;
}

function qs(params: Record<string, string | number | boolean | undefined>): string {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === '') return;
    sp.set(k, String(v));
  });
  const s = sp.toString();
  return s ? `?${s}` : '';
}

export const departmentsService = {
  list: (opts: { includeInactive?: boolean; search?: string; page?: number; pageSize?: number } = {}) =>
    medicalOrgRequest<DepartmentPaged>(
      'GET',
      `/departments${qs({
        includeInactive: opts.includeInactive ?? true,
        search: opts.search,
        page: opts.page ?? 1,
        pageSize: opts.pageSize ?? 50,
      })}`,
    ),

  stats: async () => {
    if (!isRmmsOrgCatalog()) {
      return medicalOrgRequest<DepartmentStats>('GET', '/departments/stats');
    }
    const list = await departmentsService.list({ includeInactive: true, page: 1, pageSize: 200 });
    const items = list.items ?? [];
    return {
      total: Number(list.totalCount ?? items.length),
      active: items.filter((i) => i.isActive).length,
      inactive: items.filter((i) => !i.isActive).length,
    };
  },

  get: (id: string) => medicalOrgRequest<MedicalDepartment>('GET', `/departments/${id}`),

  create: (req: DepartmentWriteRequest) =>
    medicalOrgRequest<MedicalDepartment>(
      'POST',
      '/departments',
      isRmmsOrgCatalog() ? toRmmsOrgUnitWrite(req) : req,
    ),

  update: (id: string, req: Partial<DepartmentWriteRequest> & { kind?: string }) =>
    medicalOrgRequest<MedicalDepartment>(
      'PUT',
      `/departments/${id}`,
      isRmmsOrgCatalog() ? toRmmsOrgUnitWrite(req, req.kind) : req,
    ),

  deactivate: (id: string) => medicalOrgRequest<void>('DELETE', `/departments/${id}`),
};
