import { getPermissionsCacheEntry } from '@linm-soft-org/linm-web-common-components';
import { useAdminPermissions } from './useAdminPermissions';
import { isAdminPermissionsBypass } from '../dev/isAdminPermissionsBypass';

export interface OrgCatalogWritePermissionOptions {
  writePermissionCode?: string;
  writePermissionFallbacks?: string[];
  adminWritePermissionCode: string;
  devWriteBypass?: boolean;
}

/** Write gate — admin route (useAdminPermissions) vs parcel host (JWT cache codes). */
export function useOrgCatalogWritePermission(opts: OrgCatalogWritePermissionOptions): boolean {
  const { hasPermission } = useAdminPermissions();
  const {
    writePermissionCode,
    writePermissionFallbacks = [],
    adminWritePermissionCode,
    devWriteBypass = false,
  } = opts;

  if (devWriteBypass || isAdminPermissionsBypass()) return true;

  if (writePermissionCode) {
    try {
      const codes = getPermissionsCacheEntry()?.payload?.permissionCodes;
      if (Array.isArray(codes)) {
        const candidates = [writePermissionCode, ...writePermissionFallbacks, adminWritePermissionCode];
        return candidates.some((c) => codes.includes(c));
      }
    } catch {
      /* cache miss */
    }
    return false;
  }

  return hasPermission(adminWritePermissionCode);
}
