/**
 * Nhân viên — Medical WebService local users (Kind B+D, modal).
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useNavTitle, useAppToast } from '@linm-soft-org/linm-web-common-components';
import { Button, Input, Select, TableCard, Modal, Pagination } from '../../ui';
import { useActiveStatusOptions } from '../../hooks/useAdminFormOptions';
import { useOrgCatalogWritePermission } from '../../hooks/useOrgCatalogWritePermission';
import {
  departmentsService,
  medicalUsersService,
  type MedicalDepartment,
  type MedicalStaffUser,
} from '../../services/medicalOrg';
import { isRmmsOrgCatalog } from '../../services/medicalOrg/rmmsOrgCatalog';
import type { OrgCatalogPageProps } from '../orgCatalog/orgCatalogPage.types';
import styles from '../orgCatalog/orgCatalog.module.css';

const PAGE_SIZE = 50;

const ROLE_OPTIONS = [
  { value: 'staff', label: 'Nhân viên' },
  { value: 'manager', label: 'Quản lý' },
  { value: 'admin', label: 'Quản trị' },
];

type FormMode = 'create' | 'edit' | 'view';

interface StaffForm {
  fullName: string;
  email: string;
  staffId: string;
  phone: string;
  role: string;
  departmentId: string;
  isActive: boolean;
}

const emptyForm: StaffForm = {
  fullName: '',
  email: '',
  staffId: '',
  phone: '',
  role: 'staff',
  departmentId: '',
  isActive: true,
};

const EmployeesManagementPage: React.FC<OrgCatalogPageProps> = ({
  navTitle = 'Nhân viên',
  pageTestId = 'admin-employees-page',
  createTestId = 'admin-employees-create',
  hint = isRmmsOrgCatalog()
    ? 'Danh mục nhân viên — RMMS Integration'
    : 'Danh mục nhân viên — Medical WebService (local users)',
  writePermissionCode,
  writePermissionFallbacks,
  adminWritePermissionCode = 'admin:employees:write',
  devWriteBypass,
}) => {
  useNavTitle(navTitle);
  const toast = useAppToast();
  const canWrite = useOrgCatalogWritePermission({
    writePermissionCode,
    writePermissionFallbacks,
    adminWritePermissionCode,
    devWriteBypass,
  });
  const { getActiveLabel, options: statusOptions } = useActiveStatusOptions();

  const [items, setItems] = useState<MedicalStaffUser[]>([]);
  const [depts, setDepts] = useState<MedicalDepartment[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [appliedSearch, setAppliedSearch] = useState('');
  const [includeInactive, setIncludeInactive] = useState(true);
  const [loading, setLoading] = useState(true);

  const [formOpen, setFormOpen] = useState(false);
  const [formMode, setFormMode] = useState<FormMode>('create');
  const [editing, setEditing] = useState<MedicalStaffUser | null>(null);
  const [form, setForm] = useState<StaffForm>(emptyForm);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);
  const cancelRef = useRef(false);
  const deptCancelRef = useRef(false);

  const locked = formMode === 'view';

  const loadDepts = useCallback(async () => {
    deptCancelRef.current = false;
    try {
      const result = await departmentsService.list({
        includeInactive: false,
        page: 1,
        pageSize: 200,
      });
      if (deptCancelRef.current) return;
      setDepts(result.items ?? []);
    } catch {
      /* lookup optional */
    }
  }, []);

  const load = useCallback(async () => {
    cancelRef.current = false;
    setLoading(true);
    try {
      const result = await medicalUsersService.list({
        includeInactive,
        search: appliedSearch,
        page,
        pageSize: PAGE_SIZE,
      });
      if (cancelRef.current) return;
      setItems(result.items ?? []);
      setTotal(Number(result.totalCount ?? 0));
    } catch (err: unknown) {
      if (!cancelRef.current) toast.fromError(err, 'Không thể tải danh sách nhân viên');
    } finally {
      if (!cancelRef.current) setLoading(false);
    }
  }, [appliedSearch, includeInactive, page, toast]);

  const rows = useMemo(
    () =>
      items.map((row) => {
        const dept = depts.find((d) => d.code === row.departmentId || d.id === row.departmentId);
        return dept ? { ...row, departmentName: dept.name } : row;
      }),
    [depts, items],
  );

  useEffect(() => {
    const t = setTimeout(loadDepts, 0);
    return () => {
      clearTimeout(t);
      deptCancelRef.current = true;
    };
  }, [loadDepts]);

  useEffect(() => {
    const t = setTimeout(load, 0);
    return () => {
      clearTimeout(t);
      cancelRef.current = true;
    };
  }, [load]);

  const rmmsCatalog = isRmmsOrgCatalog();
  const deptValue = (d: MedicalDepartment) => (rmmsCatalog ? d.code || d.id : d.id);
  const deptOptions = [
    { value: '', label: rmmsCatalog ? '— Chọn đơn vị —' : '— Không gán khoa —' },
    ...depts.map((d) => ({ value: deptValue(d), label: d.code ? `${d.code} — ${d.name}` : d.name })),
  ];

  const roleLabel = (role?: string) =>
    ROLE_OPTIONS.find((o) => o.value === (role ?? '').toLowerCase())?.label ?? role ?? '—';

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm);
    setFieldErrors({});
    setFormMode('create');
    setFormOpen(true);
  };

  const openEdit = (row: MedicalStaffUser, mode: FormMode) => {
    setEditing(row);
    setForm({
      fullName: row.fullName ?? '',
      email: row.email ?? '',
      staffId: row.staffId ?? '',
      phone: row.phone ?? '',
      role: (row.role || 'staff').toLowerCase(),
      departmentId: row.departmentId ?? '',
      isActive: row.isActive,
    });
    setFieldErrors({});
    setFormMode(mode);
    setFormOpen(true);
  };

  const closeForm = () => {
    if (saving) return;
    setFormOpen(false);
  };

  const validate = (): boolean => {
    const next: Record<string, string> = {};
    if (!form.fullName.trim()) next.fullName = 'Họ tên là bắt buộc';
    if (rmmsCatalog && !form.departmentId.trim()) next.departmentId = 'Đơn vị là bắt buộc';
    setFieldErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSave = async () => {
    if (locked || !canWrite) return;
    if (!validate()) return;
    setSaving(true);
    try {
      const dept = depts.find((d) => d.id === form.departmentId || d.code === form.departmentId);
      const payload = {
        fullName: form.fullName.trim(),
        email: form.email.trim() || null,
        role: form.role,
        departmentId: form.departmentId || null,
        departmentName: dept?.name ?? null,
        staffId: form.staffId.trim() || null,
        phone: form.phone.trim() || null,
        isActive: form.isActive,
        username: editing?.username ?? null,
        orgCode: rmmsCatalog ? dept?.code || form.departmentId || null : null,
      };
      if (editing) await medicalUsersService.update(editing.id, payload);
      else await medicalUsersService.create(payload);
      toast.success(editing ? 'Đã cập nhật nhân viên' : 'Đã tạo nhân viên');
      setFormOpen(false);
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể lưu nhân viên');
    } finally {
      setSaving(false);
    }
  };

  const handleDeactivate = async (row: MedicalStaffUser) => {
    if (!canWrite) return;
    try {
      await medicalUsersService.deactivate(row.id);
      toast.success('Đã ngừng hoạt động nhân viên');
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể ngừng hoạt động');
    }
  };

  const modalTitle =
    formMode === 'create' ? 'Thêm nhân viên' : formMode === 'edit' ? 'Chỉnh sửa nhân viên' : 'Xem nhân viên';

  return (
    <div className={styles.page} data-testid={pageTestId}>
      <div className={styles.header}>
        <div>
          <h1 className={styles.title}>
            <i className="fas fa-user-nurse" /> {navTitle}
          </h1>
          <p className={styles.hint}>{hint}</p>
        </div>
        <div className={styles.headerActions}>
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Tìm tên, mã NV, email"
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                setPage(1);
                setAppliedSearch(search.trim());
              }
            }}
          />
          <Button
            variant="secondary"
            onClick={() => {
              setPage(1);
              setAppliedSearch(search.trim());
            }}
          >
            Tìm
          </Button>
          <Button
            variant={includeInactive ? 'secondary' : 'primary'}
            onClick={() => {
              setIncludeInactive((v) => !v);
              setPage(1);
            }}
          >
            {includeInactive ? 'Tất cả' : 'Đang hoạt động'}
          </Button>
          <Button variant="secondary" onClick={load}>
            <i className="fas fa-rotate" /> Làm mới
          </Button>
          {canWrite && (
            <Button variant="primary" onClick={openCreate} data-testid={createTestId}>
              <i className="fas fa-plus" /> Thêm
            </Button>
          )}
        </div>
      </div>

      <TableCard>
        {loading && <div className={styles.emptyState}>Đang tải dữ liệu...</div>}
        {!loading && rows.length === 0 && (
          <div className={styles.emptyState}>
            <i className="fas fa-user-nurse" />
            <p>Chưa có nhân viên</p>
          </div>
        )}
        {!loading && rows.length > 0 && (
          <div className={styles.tableWrapper}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Mã NV</th>
                  <th>Họ tên</th>
                  <th>Khoa/phòng</th>
                  <th>Vai trò</th>
                  <th>Điện thoại</th>
                  <th>Trạng thái</th>
                  <th className={styles.actionsCell}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row, idx) => (
                  <tr key={row.id} className={styles.clickableRow} onClick={() => openEdit(row, 'view')}>
                    <td>{(page - 1) * PAGE_SIZE + idx + 1}</td>
                    <td>
                      {row.staffId ? (
                        <span className={styles.codeBadge}>{row.staffId}</span>
                      ) : (
                        <span className={styles.na}>—</span>
                      )}
                    </td>
                    <td>{row.fullName}</td>
                    <td>{row.departmentName || <span className={styles.na}>—</span>}</td>
                    <td>{roleLabel(row.role)}</td>
                    <td>{row.phone || <span className={styles.na}>—</span>}</td>
                    <td>
                      <span className={`${styles.statusBadge} ${row.isActive ? styles.active : styles.inactive}`}>
                        {getActiveLabel(row.isActive)}
                      </span>
                    </td>
                    <td className={styles.actionsCell} onClick={(e) => e.stopPropagation()}>
                      <button className={styles.viewBtn} title="Xem" onClick={() => openEdit(row, 'view')}>
                        <i className="fas fa-eye" />
                      </button>
                      {canWrite && (
                        <button className={styles.editBtn} title="Sửa" onClick={() => openEdit(row, 'edit')}>
                          <i className="fas fa-pen" />
                        </button>
                      )}
                      {canWrite && row.isActive && (
                        <button className={styles.deleteBtn} title="Ngừng hoạt động" onClick={() => handleDeactivate(row)}>
                          <i className="fas fa-ban" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </TableCard>

      {total > PAGE_SIZE && (
        <div className={styles.pager}>
          <Pagination
            currentPage={page}
            totalPages={Math.max(1, Math.ceil(total / PAGE_SIZE))}
            totalCount={total}
            pageSize={PAGE_SIZE}
            onPageChange={setPage}
          />
        </div>
      )}

      <Modal isOpen={formOpen} onClose={closeForm} title={modalTitle} size="lg" closeOnOverlayClick={!saving}>
        <div className={styles.formWrapper}>
          <div className={styles.formRow}>
            <Input
              label="Họ tên"
              value={form.fullName}
              onChange={(e) => setForm((f) => ({ ...f, fullName: e.target.value }))}
              error={fieldErrors.fullName}
              required
              readOnly={locked}
              fullWidth
            />
            <Input
              label="Mã nhân viên"
              value={form.staffId}
              onChange={(e) => setForm((f) => ({ ...f, staffId: e.target.value.toUpperCase() }))}
              readOnly={locked}
              fullWidth
            />
          </div>
          <div className={styles.formRow}>
            <Input
              label="Email"
              type="email"
              value={form.email}
              onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))}
              readOnly={locked}
              fullWidth
            />
            <Input
              label="Điện thoại"
              value={form.phone}
              onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))}
              readOnly={locked}
              fullWidth
            />
          </div>
          <div className={styles.formRow}>
            <Select
              label="Khoa/phòng"
              value={form.departmentId}
              onChange={(e) => setForm((f) => ({ ...f, departmentId: e.target.value }))}
              options={deptOptions}
              disabled={locked}
              fullWidth
            />
            <Select
              label="Vai trò"
              value={form.role}
              onChange={(e) => setForm((f) => ({ ...f, role: e.target.value }))}
              options={ROLE_OPTIONS}
              disabled={locked}
              fullWidth
            />
          </div>
          <Select
            label="Trạng thái"
            value={form.isActive ? 'active' : 'inactive'}
            onChange={(e) => setForm((f) => ({ ...f, isActive: e.target.value === 'active' }))}
            options={
              statusOptions.length >= 2
                ? statusOptions
                : [
                    { value: 'active', label: 'Hoạt động' },
                    { value: 'inactive', label: 'Ngừng hoạt động' },
                  ]
            }
            disabled={locked}
            fullWidth
          />
        </div>
        <div className={styles.modalFooter}>
          <button className={styles.cancelBtn} onClick={closeForm} disabled={saving}>
            {locked ? 'Đóng' : 'Hủy'}
          </button>
          {!locked && canWrite && (
            <button className={styles.saveBtn} onClick={handleSave} disabled={saving}>
              {saving ? 'Đang lưu...' : 'Lưu'}
            </button>
          )}
        </div>
      </Modal>
    </div>
  );
};

export default EmployeesManagementPage;
