import React from 'react';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';
import { jobsService, type ExternalSyncImportPipelineStatus } from '../../../services/jobs';
import { JobDetailCollapsibleSection } from './JobDetailMetaGrid';
import { ExternalSyncImportPipelinePanel } from './ExternalSyncImportPipelinePanel';
import { isExternalSyncRunActive } from '../jobStatusDisplay';
import { useExternalSyncAutoRefreshSettings } from '../useExternalSyncAutoRefreshSettings';
import type { DataSyncRunDetail } from '../../../services/jobs/dataSyncModels';

export type ExternalSyncRunPipelineSectionProps = {
  runDetail: DataSyncRunDetail;
};

export const ExternalSyncRunPipelineSection: React.FC<ExternalSyncRunPipelineSectionProps> = ({
  runDetail,
}) => {
  const toast = useAppToast();
  const autoRefresh = useExternalSyncAutoRefreshSettings();
  const [status, setStatus] = React.useState<ExternalSyncImportPipelineStatus | null>(null);
  const [loading, setLoading] = React.useState(false);
  const [renumberRunning, setRenumberRunning] = React.useState(false);

  const connectorKey = runDetail.setsRequested[0] ?? 'reva-fm-hoa-don';
  const fromDate = runDetail.conversionSummary?.fromDate ?? null;
  const toDate = runDetail.conversionSummary?.toDate ?? null;
  const isReva = runDetail.setsRequested.some((s) => s.toLowerCase().startsWith('reva-fm'));

  const load = React.useCallback(() => {
    if (!isReva) return;
    setLoading(true);
    jobsService
      .getExternalSyncImportPipelineStatus({
        fromDate,
        toDate,
        dataSyncRunId: runDetail.id,
        connectorKey,
      })
      .then(setStatus)
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoading(false));
  }, [connectorKey, fromDate, isReva, runDetail.id, toDate, toast]);

  React.useEffect(() => {
    load();
  }, [load]);

  React.useEffect(() => {
    if (
      !autoRefresh.settings.enabled
      || autoRefresh.intervalMs <= 0
      || !isReva
      || !isExternalSyncRunActive(runDetail.status, runDetail.checkpointSummary)
    ) {
      return undefined;
    }
    const timer = window.setInterval(load, autoRefresh.intervalMs);
    return () => window.clearInterval(timer);
  }, [
    autoRefresh.intervalMs,
    autoRefresh.settings.enabled,
    isReva,
    load,
    runDetail.checkpointSummary,
    runDetail.status,
  ]);

  const handleRenumberPost = React.useCallback(() => {
    if (!status) return;

    const renumber = status.awaitingRenumberCount ?? 0;
    const post = status.awaitingPostCount ?? 0;
    const total = renumber + post;
    if (total === 0 && !status.activeRunFinalize?.isAwaitingFinalize) {
      toast.warning('Không có chứng từ cần đánh số hoặc ghi sổ trong phạm vi run này.');
      return;
    }

    const range =
      fromDate && toDate ? `\nKhoảng ngày HĐ: ${fromDate} → ${toDate}` : '';
    const ok = window.confirm(
      `Đánh số và ghi sổ chứng từ import run ${runDetail.id}?` +
        `\n· Chờ đánh số (FM-HD-* / FM-PT-* / FM-PC-*): ${renumber.toLocaleString('vi-VN')}` +
        `\n· Chờ ghi sổ (INV-* / PT-* / PC-*): ${post.toLocaleString('vi-VN')}` +
        range +
        '\n\nNâng mức xử lý → 9 và enqueue ghi sổ (giống Phê duyệt trên ERP).',
    );
    if (!ok) return;

    setRenumberRunning(true);
    jobsService
      .triggerExternalSyncVoucherRenumber({
        fromDate,
        toDate,
        dataSyncRunId: runDetail.id,
        connectorKey,
        repostAfterRenumber: true,
      })
      .then((result) => {
        if (result.accepted) {
          toast.success(
            `Đã khởi chạy đánh số và ghi sổ` +
              (result.dataSyncRunId ? ` (run ${result.dataSyncRunId.slice(0, 8)}…)` : '') +
              ` — ${result.invoicesRenumbered.toLocaleString('vi-VN')} HĐ · ` +
              `${result.receiptsRenumbered.toLocaleString('vi-VN')} PT trong hàng đợi. Theo dõi pipeline bên dưới.`,
          );
        } else {
          toast.success(
            `Đã đánh số ${result.invoicesRenumbered.toLocaleString('vi-VN')} HĐ · ` +
              `${result.receiptsRenumbered.toLocaleString('vi-VN')} PT` +
              (result.postEventsEnqueued
                ? ` — enqueue ghi sổ ${result.postEventsEnqueued.toLocaleString('vi-VN')}`
                : '') +
              (result.firstPostEventId ? ` (event ${result.firstPostEventId.slice(0, 8)}…)` : ''),
          );
        }
        load();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRenumberRunning(false));
  }, [connectorKey, fromDate, load, runDetail.id, status, toDate, toast]);

  if (!isReva) return null;

  return (
    <JobDetailCollapsibleSection title="Pipeline import → ghi sổ" defaultOpen>
      <ExternalSyncImportPipelinePanel
        status={status}
        loading={loading}
        onRefresh={load}
        onRenumberPost={handleRenumberPost}
        renumberPostRunning={renumberRunning}
        runDetail={runDetail}
      />
    </JobDetailCollapsibleSection>
  );
};

export default ExternalSyncRunPipelineSection;
