import React from 'react';
import { InAppLink } from '../../router/InAppLink';
import { Button } from '../../ui';
import { connectorLabel } from './externalSyncRunDisplay';
import { useExternalSyncMonthSplitChain } from './useExternalSyncMonthSplitChain';

const stackStyle: React.CSSProperties = {
  position: 'fixed',
  right: 16,
  bottom: 16,
  zIndex: 1100,
  display: 'flex',
  flexDirection: 'column',
  gap: 8,
  maxWidth: 440,
};

const boxStyle: React.CSSProperties = {
  padding: '10px 12px',
  borderRadius: 8,
  border: '1px solid #93c5fd',
  background: '#eff6ff',
  color: '#1e3a8a',
  fontSize: 13,
  lineHeight: 1.45,
  boxShadow: '0 8px 24px rgba(15, 23, 42, 0.16)',
};

const ExternalSyncMonthSplitChainHost: React.FC = () => {
  const { chains, stopChain } = useExternalSyncMonthSplitChain();
  if (chains.length === 0) return null;

  return (
    <div style={stackStyle} data-testid="month-split-chain-banner">
      {chains.map((chain) => {
        const step = chain.completed.length + 1;
        const remain = chain.remaining.length;
        return (
          <div key={chain.connectorKey} style={boxStyle} data-testid={`month-split-chain-${chain.connectorKey}`}>
            <strong>Tách tháng tuần tự</strong>
            {' — '}
            {connectorLabel(chain.connectorKey)} · {step}/{chain.total} · {chain.currentSlice.label}
            {remain > 0 ? ` · còn ${remain} tháng` : ' · chờ run hiện tại xong'}
            <div style={{ display: 'flex', gap: 8, marginTop: 8, flexWrap: 'wrap', alignItems: 'center' }}>
              <InAppLink to={`/admin/jobs/external-runs?runId=${encodeURIComponent(chain.currentRunId)}`}>
                Mở run hiện tại
              </InAppLink>
              <Button
                type="button"
                variant="secondary"
                onClick={() => stopChain(chain.connectorKey)}
                data-testid={`month-split-chain-stop-${chain.connectorKey}`}
              >
                Dừng chuỗi
              </Button>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default ExternalSyncMonthSplitChainHost;
