export const connectorLabel = (configKey: string): string =>
  EXTERNAL_CONNECTOR_LABELS[configKey] ?? configKey;

const GUID_LIKE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export const isGuidLikeLabel = (value?: string | null): boolean =>
  Boolean(value?.trim() && GUID_LIKE.test(value.trim()));

/** Nhãn job theo trigger / connector / voucherTypeLabel — không dùng companyId Guid. */
export const formatExternalRunJobLabels = (run: {
  trigger?: string | null;
  setsRequested?: string[];
  setResults?: ExternalSyncSetResult[];
}): string[] => {
  const trigger = run.trigger?.trim();
  if (trigger && EXTERNAL_TRIGGER_LABELS[trigger]) {
    return [EXTERNAL_TRIGGER_LABELS[trigger]];
  }

  const fromSets = (run.setsRequested ?? [])
    .map((setName) => connectorLabel(setName))
    .filter((label) => label.trim().length > 0);
  if (fromSets.length > 0) return fromSets;

  const fromResults = (run.setResults ?? [])
    .map((s) => s.voucherTypeLabel?.trim())
    .filter((label): label is string => Boolean(label));
  if (fromResults.length > 0) return fromResults;

  if (trigger && !isGuidLikeLabel(trigger)) return [trigger];
  return [];
};

export const formatExternalRunJobLabel = (run: {
  trigger?: string | null;
  setsRequested?: string[];
  setResults?: ExternalSyncSetResult[];
}): string => {
  const labels = formatExternalRunJobLabels(run);
  if (labels.length > 0) return labels.join(', ');
  return 'Sync REVA FM';
};

/** Ẩn companyCode nếu BE lưu nhầm Guid tenant thay vì mã công ty. */
export const formatExternalRunCompanyLabel = (
  companyCode?: string | null,
  companyName?: string | null,
): string | null => {
  const code = companyCode?.trim();
  if (!code || GUID_LIKE.test(code)) return companyName?.trim() || null;
  return companyName?.trim() ? `${code} · ${companyName.trim()}` : code;
};

export const resolveExternalRunDisplayStatus = (run: {
  status: string;
  progressPercent?: number;
  documentsConverted?: number;
  documentsSkipped?: number;
  documentsTotal?: number;
  checkpointSummary?: { failed: number; pending?: number; processing?: number; total?: number };
  /** phase từ orchestration — finalize mở thì giữ Running (không giả Partial). */
  phase?: string | null;
  /** Search 0/N trang — cấm Hoàn tất (Done) khi pull chưa xong. */
  totalPages?: number;
  pagesCompleted?: number;
}): string => {
  const failed = run.checkpointSummary?.failed ?? 0;
  const phase = run.phase?.trim().toLowerCase() ?? '';
  const finalizeOpen =
    phase === 'finalize' || phase === 'awaitingfinalize';
  const totalPages = run.totalPages ?? 0;
  const pagesCompleted = run.pagesCompleted ?? 0;
  const searchIncomplete = totalPages > 0 && pagesCompleted < totalPages;
  const probe = run.documentsTotal ?? 0;
  const pulled = (run.documentsConverted ?? 0) + (run.documentsSkipped ?? 0) + failed;
  const probeShortfall = probe > 0 && pulled < probe;

  // Search còn trang — Pending/Success giả → InProgress (Running), không Done.
  if (searchIncomplete && (run.status === 'Success' || run.status === 'Running'))
    return 'Running';

  if ((phase === 'purge' || phase === 'init') && (run.status === 'Success' || run.status === 'Running'))
    return 'Running';

  // Trust BE effective status khi đang đánh số / Running thật — cấm FE giả Partial (ẩn Retry).
  if (finalizeOpen && run.status === 'Running')
    return 'Running';

  if (run.checkpointSummary && failed > 0 && run.status === 'Success') {
    return 'Partial';
  }

  if (probeShortfall && (run.status === 'Success' || run.status === 'Partial'))
    return 'Partial';

  return run.status;
};

export const resolveExternalRunListDisplayStatus = (run: DataSyncRunListItem): string =>
  resolveExternalRunDisplayStatus({
    status: run.status,
    progressPercent: run.progressPercent,
    documentsConverted: run.documentsConverted,
    documentsSkipped: run.documentsSkipped,
    documentsTotal: run.documentsTotal,
    checkpointSummary: {
      failed: run.documentsFailed ?? 0,
      pending: run.checkpointPending ?? 0,
      processing: run.checkpointProcessing ?? 0,
      total: run.documentsTotal ?? 0,
    },
  });

export const formatExternalRunStatsLine = (run: DataSyncRunDetail | DataSyncRunListItem): string => {
  const summary = 'conversionSummary' in run ? run.conversionSummary : undefined;
  const checkpointTotal =
    'checkpointSummary' in run ? (run.checkpointSummary?.total ?? 0) : 0;
  const checkpointDone =
    'checkpointSummary' in run && checkpointTotal > 0
      ? run.checkpointSummary?.done
      : undefined;
  const checkpointFailed =
    'checkpointSummary' in run ? run.checkpointSummary?.failed ?? 0 : 0;
  const checkpointSkipped =
    'checkpointSummary' in run && checkpointTotal > 0
      ? run.checkpointSummary?.skipped
      : undefined;
  const checkpointPending =
    'checkpointSummary' in run
      ? (run.checkpointSummary?.pending ?? 0)
      : ('checkpointPending' in run ? (run.checkpointPending ?? 0) : 0);
  const checkpointProcessing =
    'checkpointSummary' in run
      ? (run.checkpointSummary?.processing ?? 0)
      : ('checkpointProcessing' in run ? (run.checkpointProcessing ?? 0) : 0);

  const converted =
    checkpointDone ?? run.documentsConverted ?? summary?.documentsConverted ?? 0;
  // Checkpoint SSOT khi đã có total — tránh SummaryJson stale sau Retry (vẫn hiện N lỗi).
  const failed =
    checkpointTotal > 0
      ? checkpointFailed
      : (run.documentsFailed ?? summary?.documentsFailed ?? 0);
  const probeFromConversion = summary?.documentsTotal ?? 0;
  const listOrDetailTotal = run.documentsTotal ?? 0;
  const skipped = checkpointSkipped ?? summary?.documentsSkipped ?? run.documentsSkipped ?? 0;
  const pullOnly = summary?.documentsPullOnly ?? 0;
  const processed = converted + skipped + failed + pullOnly;
  const inFlight = checkpointPending + checkpointProcessing;

  // POS probe (vd. 382k) là mục tiêu SSOT — Failed/Partial/Success giữ cùng mẫu số như Running.
  const scopeTotal = Math.max(checkpointTotal, listOrDetailTotal, probeFromConversion);

  const parts: string[] = [`${converted.toLocaleString('vi-VN')} tạo mới`];
  if (skipped > 0) {
    parts.push(`${skipped.toLocaleString('vi-VN')} skip`);
  }
  if (failed > 0) {
    parts.push(`${failed.toLocaleString('vi-VN')} lỗi`);
  }
  if (inFlight > 0) {
    parts.push(`${inFlight.toLocaleString('vi-VN')} đang chờ`);
  }

  if (scopeTotal > 0) {
    if (scopeTotal > processed) {
      parts.push(
        `${processed.toLocaleString('vi-VN')}/${scopeTotal.toLocaleString('vi-VN')} mục tiêu`,
      );
    } else {
      parts.push(`${scopeTotal.toLocaleString('vi-VN')} tổng`);
    }
  }
  return parts.join(' · ');
};

/** Confirm text cho Dừng run — số thật Pending/Processing (+ event ước lượng), không dùng probe POS. */
export const formatStopExternalSyncConfirm = (run: DataSyncRunDetail): string => {
  const s = run.checkpointSummary;
  const pending = s?.pending ?? 0;
  const processing = s?.processing ?? 0;
  const inFlightCp = pending + processing;
  const orch = run.orchestration;
  const eventHint =
    (orch?.detailBatchEventsInFlight ?? 0)
    + (orch?.detailPoolPending ?? 0)
    + (orch?.detailSlotsInUse ?? 0);
  const lines = [
    'Dừng run sync này?',
    '',
    `• ${inFlightCp.toLocaleString('vi-VN')} checkpoint Pending/Processing → Failed`,
    `• Event Pending/Processing của run sẽ bị hủy` +
      (eventHint > 0 ? ` (ước lượng ~${eventHint.toLocaleString('vi-VN')} slot/batch đang mở)` : ''),
    '• Sample Created (chờ đánh số) giữ nguyên — dùng «Đánh số và Post» sau nếu cần',
    '',
    'Lưu ý: số «mục tiêu / POS probe» trên UI không phải hàng đợi đang chạy.',
  ];
  return lines.join('\n');
};

/** Giữ bản lỗi mới nhất theo mã chứng từ (retry có thể ghi nhiều sample). */
export const dedupeExternalErrorSamples = (
  samples: ExternalSyncErrorSample[] | undefined,
): ExternalSyncErrorSample[] => {
  const byKey = new Map<string, ExternalSyncErrorSample>();
  for (const sample of samples ?? []) {
    const key = sample.documentKey?.trim() || sample.message.trim() || `__${byKey.size}`;
    const existing = byKey.get(key);
    if (!existing) {
      byKey.set(key, sample);
      continue;
    }
    const sampleAt = sample.atUtc ? Date.parse(sample.atUtc) : 0;
    const existingAt = existing.atUtc ? Date.parse(existing.atUtc) : 0;
    if (sampleAt >= existingAt) {
      byKey.set(key, sample);
    }
  }
  return [...byKey.values()];
};

export const formatCheckpointSummaryHint = (summary: {
  total: number;
  done: number;
  skipped: number;
  failed: number;
  pending: number;
  processing: number;
}): string => {
  const parts = [`${summary.total.toLocaleString('vi-VN')} checkpoint`];
  if (summary.done > 0) parts.push(`${summary.done.toLocaleString('vi-VN')} tạo mới`);
  if (summary.skipped > 0) parts.push(`${summary.skipped.toLocaleString('vi-VN')} skip`);
  if (summary.failed > 0) parts.push(`${summary.failed.toLocaleString('vi-VN')} lỗi`);
  if (summary.processing > 0) parts.push(`${summary.processing.toLocaleString('vi-VN')} Processing`);
  if (summary.pending > 0) parts.push(`${summary.pending.toLocaleString('vi-VN')} Pending`);
  return parts.join(' · ');
};

export const buildErrorMessageMap = (
  samples: DataSyncRunDetail['errorSamples'],
  checkpoints?: Array<{ documentKey: string; errorMessage?: string | null }>,
): Map<string, string> => {
  const map = new Map<string, string>();
  for (const sample of samples ?? []) {
    if (sample.documentKey) {
      map.set(sample.documentKey, sample.message);
    }
  }
  for (const cp of checkpoints ?? []) {
    if (cp.documentKey && cp.errorMessage && !map.has(cp.documentKey)) {
      map.set(cp.documentKey, cp.errorMessage);
    }
  }
  return map;
};

/** Pin run from detail API when list page does not include it (deep link / pagination). */
export const runDetailToListItem = (detail: DataSyncRunDetail): DataSyncRunListItem => ({
  id: detail.id,
  companyCode: detail.companyCode,
  companyName: detail.companyName,
  status: detail.status,
  trigger: detail.trigger,
  environmentName: detail.environmentName,
  kind: detail.kind,
  startedAtUtc: detail.startedAtUtc,
  finishedAtUtc: detail.finishedAtUtc,
  setsRequested: detail.setsRequested,
  progressPercent: detail.progressPercent,
  documentsConverted:
    (detail.checkpointSummary?.total ?? 0) > 0
      ? detail.checkpointSummary.done
      : detail.conversionSummary?.documentsConverted,
  documentsSkipped:
    (detail.checkpointSummary?.total ?? 0) > 0
      ? detail.checkpointSummary.skipped
      : detail.conversionSummary?.documentsSkipped,
  documentsTotal:
    (detail.checkpointSummary?.total ?? 0) > 0
      ? detail.checkpointSummary.total
      : detail.conversionSummary?.documentsTotal,
  documentsFailed:
    (detail.checkpointSummary?.total ?? 0) > 0
      ? detail.checkpointSummary.failed
      : detail.conversionSummary?.documentsFailed ?? 0,
});

/** ms → «2 phút 15 giây» / «450 ms». */
export const formatDurationMs = (ms?: number | null): string => {
  if (ms == null || ms <= 0) return '—';
  if (ms < 1000) return `${Math.round(ms)} ms`;
  const totalSec = Math.round(ms / 1000);
  if (totalSec < 60) return `${totalSec} giây`;
  const min = Math.floor(totalSec / 60);
  const sec = totalSec % 60;
  if (min < 60) return sec > 0 ? `${min} phút ${sec} giây` : `${min} phút`;
  const hour = Math.floor(min / 60);
  const remMin = min % 60;
  return remMin > 0 ? `${hour} giờ ${remMin} phút` : `${hour} giờ`;
};

export const formatExternalOrchestrationHeroLine = (
  orch: NonNullable<DataSyncRunDetail['orchestration']>,
): string => {
  const parts: string[] = [];
  if (orch.leaderWorkerId) {
    parts.push(`Leader: ${orch.leaderWorkerId}`);
  } else if (orch.dispatchMode === 'leaderPool') {
    parts.push('Leader: leaderPool (chưa dispatch)');
  }

  if (orch.isLedgerRepost) {
    const postCap = orch.totalDetailParallelJobs ?? orch.searchLaneCount * orch.detailParallelJobs;
    parts.push(`Re-post cap ${postCap} · slot ${orch.detailSlotsInUse}/${postCap}`);
  } else {
    const batchSize = orch.detailBatchSize ?? orch.detailParallelJobs;
    const concurrent = Math.max(1, orch.concurrentDetailBatches ?? 1);
    const docsCap =
      orch.maxInFlightDocsTotal ??
      orch.totalDetailParallelJobs ??
      orch.searchLaneCount * batchSize * concurrent;
    parts.push(
      `Run ${orch.searchLaneCount} leader · ${batchSize} CT/batch (= 1 POS batch call) · cap ${docsCap} docs`,
    );
    const batchInFlight = orch.detailBatchEventsInFlight;
    parts.push(
      `Docs ${orch.detailSlotsInUse}/${docsCap}` +
        (batchInFlight != null ? ` · batch job ${batchInFlight}` : '') +
        (orch.detailPoolPending > 0
          ? ` · pool ${orch.detailPoolPending.toLocaleString('vi-VN')} chờ`
          : ''),
    );
  }

  if (orch.searchMode === 'parallelLanes' && orch.totalPages > 0) {
    parts.push(`Search ${orch.pagesCompleted}/${orch.totalPages} trang · ${orch.searchLaneCount} lane`);
  } else if (orch.searchMode === 'sequential' && orch.totalPages > 0) {
    parts.push(`Search ${orch.pagesCompleted}/${orch.totalPages} trang`);
  }
  if (orch.runDurationMs != null) {
    parts.push(`Tổng ${formatDurationMs(orch.runDurationMs)}`);
  }
  return parts.join(' · ');
};

/** Clipboard text: khoảng ngày run + mỗi mã CT lỗi một dòng. */
export const formatFailedVoucherCopyText = (
  fromDate: string | null | undefined,
  toDate: string | null | undefined,
  documentKeys: string[],
): string => {
  const seen = new Set<string>();
  const keys: string[] = [];
  for (const raw of documentKeys) {
    const key = raw.trim();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    keys.push(key);
  }
  const from = fromDate?.trim() ?? '';
  const to = toDate?.trim() ?? '';
  const range = from && to ? `${from} → ${to}` : from || to;
  return [range, ...keys].filter(Boolean).join('\n');
};
