import React from 'react';
import { createRoot } from 'react-dom/client';
import singleSpaReact from 'single-spa-react';
import { OrgCatalogParcelShell } from '../components/OrgCatalogParcelShell';
import EmployeesManagementPage from '../pages/EmployeesManagementPage';
import type { OrgCatalogPageProps } from '../pages/orgCatalog/orgCatalogPage.types';

const EmployeesManagementWithShell: React.FC<OrgCatalogPageProps> = (props) => (
  <OrgCatalogParcelShell>
    <EmployeesManagementPage {...props} />
  </OrgCatalogParcelShell>
);

export type EmployeesManagementParcelProps = OrgCatalogPageProps;

export const EmployeesManagementParcel = singleSpaReact({
  React,
  ReactDOMClient: { createRoot },
  rootComponent: EmployeesManagementWithShell,
  renderType: 'createRoot',
  errorBoundary(error) {
    throw error;
  },
});
