import React from 'react';
import { Button } from '../../../ui';
import type { ExternalSyncImportPipelineStatus } from '../../../services/jobs';
import type { DataSyncRunDetail } from '../../../services/jobs/dataSyncModels';
import styles from '../JobInternalPage.module.css';

/** Document type label map (BE key → VN hiển thị). */
const DOC_TYPE_LABEL: Record<string, string> = {
  Invoice: 'Hóa đơn',
  Receipt: 'Phiếu thu / Báo có',
  Payment: 'Phiếu chi / Báo nợ',
};

/** Summary card showing aggregate count for a pipeline status. */
const SummaryCard: React.FC<{
  label: string;
  count: number;
  color: string;
  bg: string;
}> = ({ label, count, color, bg }) => (
  <div
    style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      padding: '8px 16px',
      borderRadius: 8,
      background: bg,
      border: `1px solid ${color}33`,
      minWidth: 100,
    }}
  >
    <span style={{ fontSize: 22, fontWeight: 700, color, fontVariantNumeric: 'tabular-nums' }}>
      {count.toLocaleString('vi-VN')}
    </span>
    <span style={{ fontSize: 11, color: '#64748b', marginTop: 2 }}>{label}</span>
  </div>
);

export type ExternalSyncImportPipelinePanelProps = {
  status: ExternalSyncImportPipelineStatus | null;
  loading: boolean;
  onRefresh: () => void;
  onRenumberPost?: () => void;
  renumberPostRunning?: boolean;
  renumberPostDisabled?: boolean;
  dataTestId?: string;
  runDetail?: DataSyncRunDetail | null;
};

export const ExternalSyncImportPipelinePanel: React.FC<ExternalSyncImportPipelinePanelProps> = ({
  status,
  loading,
  onRefresh,
  onRenumberPost,
  renumberPostRunning = false,
  renumberPostDisabled,
  dataTestId = 'external-sync-import-pipeline-panel',
  runDetail: _runDetail,
}) => {
  if (!status && !loading) return null;

  const awaitingRenumber = status?.awaitingRenumberCount ?? 0;
  const awaitingPost = status?.awaitingPostCount ?? 0;
  const posted = status?.postedCount ?? 0;
  const pipelineWorkCount = awaitingRenumber + awaitingPost;
  const finalizeInProgress =
    status?.activeRunFinalize?.phase?.toLowerCase() === 'finalize';
  const hasPipelineWork =
    pipelineWorkCount > 0 || (status?.activeRunFinalize?.isAwaitingFinalize ?? false);
  const renumberPostDisabledResolved =
    renumberPostDisabled ??
    (renumberPostRunning || loading || finalizeInProgress || !hasPipelineWork);

  return (
    <div
      style={{
        marginTop: 16,
        padding: '16px 20px',
        border: '1px solid #e2e8f0',
        borderRadius: 8,
        background: '#fff',
        maxWidth: 960,
      }}
      data-testid={dataTestId}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, alignItems: 'center', marginBottom: 8 }}>
        <h3 style={{ margin: 0, fontSize: 16, flex: '1 1 auto' }}>Pipeline import → ghi sổ</h3>
        <Button type="button" variant="secondary" onClick={onRefresh} disabled={loading} data-testid="pipeline-refresh">
          {loading ? 'Đang tải…' : 'Làm mới'}
        </Button>
        {onRenumberPost ? (
          <Button
            type="button"
            onClick={onRenumberPost}
            disabled={renumberPostDisabledResolved}
            data-testid="pipeline-renumber-post"
          >
            {renumberPostRunning
              ? 'Đang gửi…'
              : finalizeInProgress
                ? 'Đang đánh số (nền)…'
                : 'Đánh số và Post chứng từ'}
          </Button>
        ) : null}
      </div>
      {status ? (
        <>
          <p className={styles.listHint} style={{ margin: '0 0 12px' }}>
            {status.pipelineDescription}
            {status.skipVoucherPlaceholder ? (
              <span style={{ color: '#b45309' }}> · Đang bật skip placeholder.</span>
            ) : null}
          </p>

          {/* ── Summary cards ── */}
          <div style={{ display: 'flex', gap: 12, marginBottom: 16 }}>
            <SummaryCard label="Chờ đánh số" count={awaitingRenumber} color="#d97706" bg="#fffbeb" />
            <SummaryCard label="Chờ ghi sổ" count={awaitingPost} color="#2563eb" bg="#eff6ff" />
            <SummaryCard label="Đã ghi sổ" count={posted} color="#16a34a" bg="#f0fdf4" />
            {status.failedCount > 0 && (
              <SummaryCard label="Lỗi" count={status.failedCount} color="#dc2626" bg="#fef2f2" />
            )}
          </div>

          {/* ── Type breakdown grid: Loại CT | Đã tạo | Đã đánh số | Đã ghi sổ ── */}
          {status.typeBreakdown && status.typeBreakdown.length > 0 && (
            <div
              style={{
                display: 'grid',
                gridTemplateColumns: '1fr 80px 80px 80px',
                gap: 0,
                marginBottom: 16,
                border: '1px solid #e2e8f0',
                borderRadius: 6,
                overflow: 'hidden',
                fontSize: 13,
              }}
              data-testid="pipeline-type-breakdown"
            >
              {/* Header row */}
              <div style={{ fontWeight: 600, padding: '6px 12px', background: '#f8fafc', borderBottom: '1px solid #e2e8f0' }}>Loại chứng từ</div>
              <div style={{ fontWeight: 600, padding: '6px 12px', background: '#f8fafc', borderBottom: '1px solid #e2e8f0', textAlign: 'right' }}>Đã tạo</div>
              <div style={{ fontWeight: 600, padding: '6px 12px', background: '#f8fafc', borderBottom: '1px solid #e2e8f0', textAlign: 'right' }}>Đã đánh số</div>
              <div style={{ fontWeight: 600, padding: '6px 12px', background: '#f8fafc', borderBottom: '1px solid #e2e8f0', textAlign: 'right' }}>Đã ghi sổ</div>

              {/* Data rows */}
              {status.typeBreakdown.map((row) => {
                const label = DOC_TYPE_LABEL[row.documentType] ?? row.documentType;
                const hasAny = row.createdCount + row.renumberedCount + row.postedCount > 0;
                if (!hasAny) return null;
                return (
                  <React.Fragment key={row.documentType}>
                    <div style={{ padding: '6px 12px', borderBottom: '1px solid #f1f5f9' }}>{label}</div>
                    <div style={{ padding: '6px 12px', borderBottom: '1px solid #f1f5f9', textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{row.createdCount.toLocaleString('vi-VN')}</div>
                    <div style={{ padding: '6px 12px', borderBottom: '1px solid #f1f5f9', textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{row.renumberedCount.toLocaleString('vi-VN')}</div>
                    <div style={{ padding: '6px 12px', borderBottom: '1px solid #f1f5f9', textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>{row.postedCount.toLocaleString('vi-VN')}</div>
                  </React.Fragment>
                );
              })}
            </div>
          )}

          {status.activeRunFinalize?.isAwaitingFinalize ? (
            <p
              style={{
                margin: '0 0 12px',
                padding: '8px 12px',
                background: '#eff6ff',
                borderRadius: 6,
                fontSize: 13,
              }}
              data-testid="pipeline-active-finalize"
            >
              Run <strong>{status.activeRunFinalize.runId}</strong> · phase{' '}
              <code>{status.activeRunFinalize.phase}</code>
              {status.activeRunFinalize.connectorKey
                ? ` · ${status.activeRunFinalize.connectorKey}`
                : ''}
              {status.activeRunFinalize.fromDate && status.activeRunFinalize.toDate
                ? ` · ${status.activeRunFinalize.fromDate} → ${status.activeRunFinalize.toDate}`
                : ''}{' '}
              —{' '}
              {status.activeRunFinalize.phase?.toLowerCase() === 'finalize'
                ? 'đang đánh số và ghi sổ (nền).'
                : 'đang chờ bước finalize đánh số.'}
            </p>
          ) : null}

          {/* ── Detail hint ── */}
          <p style={{ fontSize: 13, color: '#64748b', marginTop: 4 }}>
            Chi tiết từng chứng từ xem ở mục{' '}
            <strong>Mã chứng từ đã convert</strong> bên dưới.
          </p>
        </>
      ) : (
        <p className={styles.listHint}>Đang tải trạng thái pipeline…</p>
      )}
    </div>
  );
};

export default ExternalSyncImportPipelinePanel;
