/**
 * Bind this MFE's `@linm/{mf}` name. Logic SSOT:
 * `@linm-soft-org/linm-web-common-components` `applyRuntimeApiUrl`.
 */
import {
  applyRuntimeApiUrl,
  resolveRuntimeApiUrl as resolveMfRuntimeApiUrl,
} from '@linm-soft-org/linm-web-common-components';

const LINM_MF_NAME = '@linm/admin';

export function resolveRuntimeApiUrl(buildFallback?: string): string {
  return resolveMfRuntimeApiUrl(LINM_MF_NAME, buildFallback);
}

applyRuntimeApiUrl(LINM_MF_NAME, import.meta.env.VITE_API_URL as string | undefined);
