import { apiClient } from '../api';
import { BffResponse, unwrap } from '@linm-soft-org/linm-web-common-components';
import type {
  ApiKeyListItem,
  ApiKeyListQuery,
  CreateApiKeyPayload,
  CreateApiKeyResult,
  RotateApiKeyResult,
  UpdateApiKeyPayload,
} from './types';

const BASE = '/admin/apikeys';

function listQuery(params?: ApiKeyListQuery): string {
  const q = new URLSearchParams();
  const search = params?.search?.trim();
  if (search) q.set('search', search);
  if (params?.includeInactive === false) q.set('includeInactive', 'false');
  const qs = q.toString();
  return qs ? `?${qs}` : '';
}

export const apiKeysEndpoint = {
  list: async (params?: ApiKeyListQuery): Promise<ApiKeyListItem[]> => {
    const res = await apiClient.get<BffResponse<ApiKeyListItem[]>>(`${BASE}${listQuery(params)}`);
    const data = unwrap(res);
    return Array.isArray(data) ? data : [];
  },

  getById: async (id: string): Promise<ApiKeyListItem> => {
    const res = await apiClient.get<BffResponse<ApiKeyListItem>>(`${BASE}/${id}`);
    return unwrap(res);
  },

  create: async (payload: CreateApiKeyPayload): Promise<CreateApiKeyResult> => {
    const res = await apiClient.post<BffResponse<CreateApiKeyResult>>(BASE, payload);
    return unwrap(res);
  },

  update: async (id: string, payload: UpdateApiKeyPayload): Promise<ApiKeyListItem> => {
    const res = await apiClient.post<BffResponse<ApiKeyListItem>>(`${BASE}/${id}`, payload);
    return unwrap(res);
  },

  rotate: async (id: string): Promise<RotateApiKeyResult> => {
    const res = await apiClient.post<BffResponse<RotateApiKeyResult>>(`${BASE}/${id}/rotate`, {});
    return unwrap(res);
  },

  revoke: async (id: string): Promise<void> => {
    await apiClient.post<BffResponse<object>>(`${BASE}/${id}/revoke`, {});
  },

  remove: async (id: string): Promise<void> => {
    await apiClient.delete<BffResponse<object>>(`${BASE}/${id}`);
  },
};
