import React from 'react';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';
import { jobsService } from '../../services/jobs';
import { isExternalSyncRunActive } from './jobStatusDisplay';
import {
  isMonthSplitAbortStatus,
  isMonthSplitContinueStatus,
  readAllMonthSplitChains,
  readMonthSplitChain,
  subscribeMonthSplitChain,
  writeMonthSplitChain,
  type MonthSplitChain,
} from './externalSyncMonthSplit';

const POLL_MS = 15_000;
const FIRST_POLL_MS = 2_500;

export function useExternalSyncMonthSplitChain(): {
  chains: MonthSplitChain[];
  stopChain: (connectorKey: string) => void;
} {
  const toast = useAppToast();
  const [chains, setChains] = React.useState<MonthSplitChain[]>(() => readAllMonthSplitChains());
  const enqueueInFlight = React.useRef<Set<string>>(new Set());

  React.useEffect(() => subscribeMonthSplitChain(() => setChains(readAllMonthSplitChains())), []);

  const stopChain = React.useCallback(
    (connectorKey: string) => {
      writeMonthSplitChain(null, connectorKey);
      toast.info('Đã dừng chuỗi tách tháng — run hiện tại vẫn chạy.');
    },
    [toast],
  );

  const chainKey = chains.map((c) => `${c.connectorKey}:${c.currentRunId}`).join('|');

  React.useEffect(() => {
    if (!chainKey) return undefined;
    let cancelled = false;

    const tickOne = async (snapshot: MonthSplitChain) => {
      if (cancelled || enqueueInFlight.current.has(snapshot.connectorKey)) return;
      const live = readMonthSplitChain(snapshot.connectorKey);
      if (!live || live.currentRunId !== snapshot.currentRunId) return;

      try {
        const run = await jobsService.getDataSyncRun(live.currentRunId);
        if (cancelled) return;
        if (isExternalSyncRunActive(run.status, run.checkpointSummary)) return;

        if (isMonthSplitAbortStatus(run.status)) {
          writeMonthSplitChain(null, live.connectorKey);
          toast.error(
            `Chuỗi ${live.connectorKey} dừng — ${live.currentSlice.label} ${run.status} (${live.completed.length + 1}/${live.total}).`,
          );
          return;
        }

        if (!isMonthSplitContinueStatus(run.status)) {
          writeMonthSplitChain(null, live.connectorKey);
          toast.error(`Chuỗi ${live.connectorKey} dừng — trạng thái không rõ: ${run.status}.`);
          return;
        }

        const next = live.remaining[0];
        if (!next) {
          writeMonthSplitChain(null, live.connectorKey);
          toast.success(`Đã xong chuỗi ${live.connectorKey} (${live.total} run).`);
          return;
        }

        enqueueInFlight.current.add(live.connectorKey);
        const res = await jobsService.triggerExternalSync(live.connectorKey, {
          fromDate: next.fromDate,
          toDate: next.toDate,
          syncMode: live.syncMode ?? 'resync',
          resync: (live.syncMode ?? 'resync') === 'resync',
        });
        if (cancelled) return;
        writeMonthSplitChain({
          ...live,
          currentRunId: res.runId,
          currentSlice: next,
          remaining: live.remaining.slice(1),
          completed: [...live.completed, live.currentSlice],
        });
        const step = live.completed.length + 2;
        toast.success(
          `Đã enqueue ${live.connectorKey} tháng ${step}/${live.total} (${next.label}) · run ${res.runId.slice(0, 8)}…`,
        );
      } catch (e: unknown) {
        if (!cancelled) {
          toast.error(e instanceof Error ? e.message : 'Lỗi enqueue tháng tiếp theo');
        }
      } finally {
        enqueueInFlight.current.delete(snapshot.connectorKey);
      }
    };

    const tickAll = () => {
      for (const chain of readAllMonthSplitChains()) {
        void tickOne(chain);
      }
    };

    const first = window.setTimeout(tickAll, FIRST_POLL_MS);
    const interval = window.setInterval(tickAll, POLL_MS);
    return () => {
      cancelled = true;
      window.clearTimeout(first);
      window.clearInterval(interval);
    };
  }, [chainKey, toast]);

  return { chains, stopChain };
}
