/**
 * Soft caps for PlatformEventing.Runtime Admin UI (JOB-OPT / DKR-P3-RAM).
 * Recommended for host ≤2GB (Docker mem_limit ~1.5GB). Larger hosts may raise — show warn only.
 */

export const EVENTING_RUNTIME_RECOMMENDED = {
  lowWorkerMax: 4,
  lowWorkerFixed: 4,
  lowBatchSize: 5,
  highBatchSize: 8,
} as const;

/** Above these → warn (RAM/CPU spike risk trên host nhỏ). */
export const EVENTING_RUNTIME_WARN_ABOVE = {
  lowWorkerMax: 4,
  lowWorkerFixed: 4,
  lowBatchSize: 8,
  highBatchSize: 8,
} as const;

/** Above these → danger (baseline cũ 20/50 / worker 8). */
export const EVENTING_RUNTIME_DANGER_ABOVE = {
  lowWorkerMax: 8,
  lowWorkerFixed: 8,
  lowBatchSize: 20,
  highBatchSize: 20,
} as const;

export type EventingRuntimeResourceDraft = {
  lowWorkerAutoScaleEnabled?: boolean;
  lowWorkerInstanceCount?: number;
  lowWorkerInstanceCountMax?: number;
  lowBatchSize?: number;
  highBatchSize?: number;
};

export type EventingRuntimeResourceHint = {
  id: 'lowWorkerMax' | 'lowWorkerFixed' | 'lowBatchSize' | 'highBatchSize';
  level: 'warn' | 'danger';
  fieldLabel: string;
  message: string;
};

export function evaluateEventingRuntimeResourceHints(
  draft: EventingRuntimeResourceDraft,
): EventingRuntimeResourceHint[] {
  const hints: EventingRuntimeResourceHint[] = [];
  const autoScale = draft.lowWorkerAutoScaleEnabled ?? false;

  const pushWorker = (
    id: 'lowWorkerMax' | 'lowWorkerFixed',
    value: number | undefined,
    fieldLabel: string,
  ) => {
    if (value == null || !Number.isFinite(value)) return;
    const danger = EVENTING_RUNTIME_DANGER_ABOVE[id];
    const warn = EVENTING_RUNTIME_WARN_ABOVE[id];
    const rec = id === 'lowWorkerMax'
      ? EVENTING_RUNTIME_RECOMMENDED.lowWorkerMax
      : EVENTING_RUNTIME_RECOMMENDED.lowWorkerFixed;
    if (value > danger) {
      hints.push({
        id,
        level: 'danger',
        fieldLabel,
        message: `${fieldLabel}=${value} — rủi ro RAM/CPU cao (khuyến nghị ≤${rec} trên host ≤2GB).`,
      });
    } else if (value > warn) {
      hints.push({
        id,
        level: 'warn',
        fieldLabel,
        message: `${fieldLabel}=${value} — vượt khuyến nghị ≤${rec} (container ERP job host).`,
      });
    }
  };

  if (autoScale) {
    pushWorker('lowWorkerMax', draft.lowWorkerInstanceCountMax, 'Max worker / host');
  } else {
    pushWorker('lowWorkerFixed', draft.lowWorkerInstanceCount, 'Số worker / host');
  }

  const lowBatch = draft.lowBatchSize;
  if (lowBatch != null && Number.isFinite(lowBatch)) {
    if (lowBatch > EVENTING_RUNTIME_DANGER_ABOVE.lowBatchSize) {
      hints.push({
        id: 'lowBatchSize',
        level: 'danger',
        fieldLabel: 'Batch mỗi vòng (LowBatchSize)',
        message: `LowBatchSize=${lowBatch} — baseline cũ 50 gây spike RAM khi POS sync; khuyến nghị ≤${EVENTING_RUNTIME_RECOMMENDED.lowBatchSize} (cảnh báo >${EVENTING_RUNTIME_WARN_ABOVE.lowBatchSize}).`,
      });
    } else if (lowBatch > EVENTING_RUNTIME_WARN_ABOVE.lowBatchSize) {
      hints.push({
        id: 'lowBatchSize',
        level: 'warn',
        fieldLabel: 'Batch mỗi vòng (LowBatchSize)',
        message: `LowBatchSize=${lowBatch} — vượt khuyến nghị ≤${EVENTING_RUNTIME_RECOMMENDED.lowBatchSize} (cảnh báo >${EVENTING_RUNTIME_WARN_ABOVE.lowBatchSize}).`,
      });
    }
  }

  const highBatch = draft.highBatchSize;
  if (highBatch != null && Number.isFinite(highBatch)) {
    if (highBatch > EVENTING_RUNTIME_DANGER_ABOVE.highBatchSize) {
      hints.push({
        id: 'highBatchSize',
        level: 'danger',
        fieldLabel: 'Batch High (HighBatchSize)',
        message: `HighBatchSize=${highBatch} — baseline cũ 20; khuyến nghị ≤${EVENTING_RUNTIME_RECOMMENDED.highBatchSize}.`,
      });
    } else if (highBatch > EVENTING_RUNTIME_WARN_ABOVE.highBatchSize) {
      hints.push({
        id: 'highBatchSize',
        level: 'warn',
        fieldLabel: 'Batch High (HighBatchSize)',
        message: `HighBatchSize=${highBatch} — vượt khuyến nghị ≤${EVENTING_RUNTIME_RECOMMENDED.highBatchSize}.`,
      });
    }
  }

  return hints;
}
