// ─── Jobs Hub Groups ─────────────────────────────────────────────────────────

export interface JobsHubGroup {
  title: string;
  icon: string;
  items: AdminNavItem[];
}

function cardsByPath(...paths: string[]): AdminNavItem[] {
  return paths
    .map((p) => JOBS_HUB_CARDS.find((c) => c.path === p || c.accessPath === p))
    .filter((c): c is AdminNavItem => !!c);
}

