lay: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.companyScope strong {\n  font-family: monospace;\n  letter-spacing: 0.03em;\n}\n\n.linmPlatformPanel {\n  background: #ebf8ff;\n  border: 1.5px solid #90cdf4;\n  border-radius: 8px;\n  padding: 14px 16px;\n  margin-bottom: 20px;\n}\n\n.linmPlatformTitle {\n  margin: 0 0 8px;\n  font-size: 1rem;\n  font-weight: 700;\n  color: #2c5282;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.linmPlatformHint,\n.linmApiHint {\n  margin: 0 0 10px;\n  font-size: 0.88rem;\n  color: #2d3748;\n  line-height: 1.45;\n}\n\n.linmScopeOptions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 10px 16px;\n  margin-bottom: 8px;\n}\n\n.linmScopeOption {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 0.9rem;\n  cursor: pointer;\n}\n\n.linmCompanySelect {\n  min-width: 200px;\n  padding: 6px 10px;\n  border-radius: 6px;\n  border: 1px solid #cbd5e0;\n  font-size: 0.9rem;\n}\n\n.infoBanner {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  background: #fffff0;\n  border: 1px solid #ecc94b;\n  border-radius: 8px;\n  padding: 12px 14px;\n  margin-bottom: 20px;\n  font-size: 0.88rem;\n  color: #744210;\n}\n\n.infoBanner p {\n  margin: 0;\n}\n\n/* ── Warning banner ──────────────────────────────────────────────────────── */\n.warningBanner {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  background: #fff5f5;\n  border: 1.5px solid #fc8181;\n  border-radius: 8px;\n  padding: 14px 16px;\n  margin-bottom: 24px;\n  color: #c53030;\n  font-size: 0.9rem;\n}\n\n.warningBanner i {\n  font-size: 1.1rem;\n  margin-top: 2px;\n  flex-shrink: 0;\n}\n\n.warningBanner p {\n  margin: 4px 0 0;\n  color: #744210;\n  font-size: 0.85rem;\n}\n\n/* ── Scope grid ──────────────────────────────────────────────────────────── */\n.scopeGrid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n  margin-bottom: 24px;\n}\n\n@media (max-width: 600px) {\n  .scopeGr