import { medicalOrgRequest } from './client';
import { isRmmsOrgCatalog, toRmmsAppUserWrite } from './rmmsOrgCatalog';

export interface MedicalStaffUser {
  id: string;
  username: string;
  email: string;
  fullName: string;
  firstName: string;
  lastName: string;
  role: string;
  departmentId?: string | null;
  departmentName: string;
  staffId?: string | null;
  phone?: string | null;
  isActive: boolean;
}

export interface StaffPaged {
  items: MedicalStaffUser[];
  page: number;
  pageSize: number;
  totalCount: number;
}

export interface StaffWriteRequest {
  fullName: string;
  email?: string | null;
  role: string;
  departmentId?: string | null;
  departmentName?: string | null;
  staffId?: string | null;
  phone?: string | null;
  isActive: boolean;
  username?: string | null;
  orgCode?: string | null;
}

function qs(params: Record<string, string | number | boolean | undefined>): string {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v === undefined || v === '') return;
    sp.set(k, String(v));
  });
  const s = sp.toString();
  return s ? `?${s}` : '';
}

export const medicalUsersService = {
  list: (opts: {
    search?: string;
    role?: string;
    departmentId?: string;
    includeInactive?: boolean;
    page?: number;
    pageSize?: number;
  } = {}) =>
    medicalOrgRequest<StaffPaged>(
      'GET',
      `/users${qs({
        search: opts.search,
        role: opts.role,
        departmentId: opts.departmentId,
        includeInactive: opts.includeInactive ?? true,
        page: opts.page ?? 1,
        pageSize: opts.pageSize ?? 50,
      })}`,
    ),

  create: (req: StaffWriteRequest) => {
    if (!isRmmsOrgCatalog()) return medicalOrgRequest<MedicalStaffUser>('POST', '/users', req);
    const orgCode = (req.orgCode || req.departmentId || '').trim();
    if (!orgCode) throw new Error('Chọn đơn vị (phòng ban) — bắt buộc trên RMMS');
    return medicalOrgRequest<MedicalStaffUser>('POST', '/users', toRmmsAppUserWrite(req, orgCode));
  },

  update: (id: string, req: Partial<StaffWriteRequest>) => {
    if (!isRmmsOrgCatalog()) return medicalOrgRequest<MedicalStaffUser>('PUT', `/users/${id}`, req);
    const orgCode = (req.orgCode || req.departmentId || '').trim();
    if (!orgCode) throw new Error('Chọn đơn vị (phòng ban) — bắt buộc trên RMMS');
    return medicalOrgRequest<MedicalStaffUser>('PUT', `/users/${id}`, toRmmsAppUserWrite(req, orgCode));
  },

  deactivate: (id: string) => medicalOrgRequest<void>('DELETE', `/users/${id}`),
};
