import { getActiveCompanyCode, getAuthToken } from '@linm-soft-org/linm-web-common-components';
import { resolveRuntimeApiUrl } from '../../config/runtimeApiUrl';
import { isRmmsOrgCatalog, mapRmmsOrgPayload, rewriteRmmsOrgPath } from './rmmsOrgCatalog';

const DEFAULT_MEDICAL_API = 'http://localhost:5100/web-bff/api/v1';

export function medicalApiBase(): string {
  if (isRmmsOrgCatalog()) {
    return resolveRuntimeApiUrl(import.meta.env.VITE_API_URL as string | undefined);
  }
  const raw = (import.meta.env.VITE_MEDICAL_API_URL as string | undefined) || DEFAULT_MEDICAL_API;
  return raw.replace(/\/$/, '');
}

interface Envelope<T> {
  success?: boolean;
  data?: T;
  message?: string;
  error?: { message?: string };
}

async function parseError(res: Response): Promise<string> {
  try {
    const body = (await res.json()) as Envelope<unknown>;
    return body.message || body.error?.message || `HTTP ${res.status}`;
  } catch {
    return `HTTP ${res.status}`;
  }
}

export async function medicalOrgRequest<T>(
  method: string,
  path: string,
  body?: unknown,
): Promise<T> {
  const resolvedPath = isRmmsOrgCatalog() ? rewriteRmmsOrgPath(path) : path;
  const url = `${medicalApiBase()}${resolvedPath.startsWith('/') ? resolvedPath : `/${resolvedPath}`}`;
  const token = getAuthToken();
  const headers: Record<string, string> = { Accept: 'application/json' };
  if (token) headers.Authorization = `Bearer ${token}`;
  const company = getActiveCompanyCode();
  if (company) headers['X-Company-Id'] = company;
  if (body !== undefined) headers['Content-Type'] = 'application/json';

  const res = await fetch(url, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  if (res.status === 204) return undefined as T;
  if (!res.ok) throw new Error(await parseError(res));

  const json = (await res.json()) as Envelope<T>;
  if (json.success === false) {
    throw new Error(json.message || json.error?.message || 'Yêu cầu thất bại');
  }
  const data = (json.data ?? json) as T;
  return mapRmmsOrgPayload(resolvedPath, data);
}
