import React from 'react';
import styles from '../DataCleanupPage.module.css';

export type CleanupVoucherTypeOption = {
  code: string;
  name: string;
};

interface CleanupFilterBarProps {
  dateFrom: string;
  dateTo: string;
  onDateFromChange: (v: string) => void;
  onDateToChange: (v: string) => void;
  allTimeMode: boolean;
  onAllTimeModeChange: (v: boolean) => void;
  selectedVoucherTypes: string[];
  onVoucherTypesChange: (v: string[]) => void;
  availableVoucherTypes: CleanupVoucherTypeOption[];
  voucherTypesLoading?: boolean;
  scanByCompany: boolean;
  onScanByCompanyChange: (v: boolean) => void;
  isLinmContext: boolean;
  skipPlatformEvents: boolean;
  onSkipPlatformEventsChange: (v: boolean) => void;
  skipDocumentHistory: boolean;
  onSkipDocumentHistoryChange: (v: boolean) => void;
}

export const CleanupFilterBar: React.FC<CleanupFilterBarProps> = ({
  dateFrom,
  dateTo,
  onDateFromChange,
  onDateToChange,
  allTimeMode,
  onAllTimeModeChange,
  selectedVoucherTypes,
  onVoucherTypesChange,
  availableVoucherTypes,
  voucherTypesLoading = false,
  scanByCompany,
  onScanByCompanyChange,
  isLinmContext,
  skipPlatformEvents,
  onSkipPlatformEventsChange,
  skipDocumentHistory,
  onSkipDocumentHistoryChange,
}) => {
  const toggleVoucherType = (code: string) => {
    if (selectedVoucherTypes.includes(code)) {
      onVoucherTypesChange(selectedVoucherTypes.filter((c) => c !== code));
    } else {
      onVoucherTypesChange([...selectedVoucherTypes, code]);
    }
  };

  const selectAllVoucherTypes = () => {
    onVoucherTypesChange(availableVoucherTypes.map((v) => v.code));
  };

  const clearAllVoucherTypes = () => {
    onVoucherTypesChange([]);
  };

  const allSelected = availableVoucherTypes.length > 0
    && availableVoucherTypes.every((vt) => selectedVoucherTypes.includes(vt.code));

  return (
    <div className={styles.filterBar}>
      <div className={styles.filterRow}>
        {/* ── Date range ── */}
        <div className={styles.filterGroup}>
          <span className={styles.filterLabel}>Thời gian</span>
          <label className={styles.voucherTypeOption}>
            <input
              type="checkbox"
              checked={allTimeMode}
              onChange={(e) => onAllTimeModeChange(e.target.checked)}
            />
            Toàn bộ thời gian
          </label>
        </div>
        {!allTimeMode && (
          <>
            <div className={styles.filterGroup}>
              <span className={styles.filterLabel}>Từ ngày</span>
              <input
                type="date"
                className={styles.filterInput}
                value={dateFrom}
                onChange={(e) => onDateFromChange(e.target.value)}
              />
            </div>
            <div className={styles.filterGroup}>
              <span className={styles.filterLabel}>Đến ngày</span>
              <input
                type="date"
                className={styles.filterInput}
                value={dateTo}
                onChange={(e) => onDateToChange(e.target.value)}
              />
            </div>
          </>
        )}

        <div className={styles.filterSeparator} />

        {/* ── Voucher type checkboxes (SSOT: VoucherRegistry AllowCleanup) ── */}
        <div className={styles.filterGroup}>
          <span className={styles.filterLabel}>Loại chứng từ</span>
          {availableVoucherTypes.length > 0 && (
            <div className={styles.voucherTypeActions}>
              <button
                type="button"
                className={styles.voucherTypeActionBtn}
                onClick={selectAllVoucherTypes}
                disabled={allSelected}
              >
                Chọn tất cả
              </button>
              <button
                type="button"
                className={styles.voucherTypeActionBtn}
                onClick={clearAllVoucherTypes}
                disabled={selectedVoucherTypes.length === 0}
              >
                Bỏ chọn
              </button>
            </div>
          )}
          <div className={styles.voucherTypeCheckboxes}>
            {voucherTypesLoading ? (
              <span style={{ fontSize: '0.85rem', color: '#a0aec0' }}>
                Đang tải danh sách loại CT…
              </span>
            ) : availableVoucherTypes.length === 0 ? (
              <span style={{ fontSize: '0.85rem', color: '#a0aec0' }}>
                (Không có loại CT AllowCleanup)
              </span>
            ) : (
              availableVoucherTypes.map((vt) => (
                <label key={vt.code} className={styles.voucherTypeOption}>
                  <input
                    type="checkbox"
                    checked={selectedVoucherTypes.includes(vt.code)}
                    onChange={() => toggleVoucherType(vt.code)}
                  />
                  {vt.name}
                </label>
              ))
            )}
          </div>
        </div>

        {isLinmContext && (
          <>
            <div className={styles.filterSeparator} />
            <div className={styles.filterGroup}>
              <span className={styles.filterLabel}>Chi tiết đơn vị</span>
              <label className={styles.voucherTypeOption}>
                <input
                  type="checkbox"
                  checked={scanByCompany}
                  onChange={(e) => onScanByCompanyChange(e.target.checked)}
                />
                Hiển thị chi tiết theo từng đơn vị
              </label>
              <span style={{ fontSize: '0.8rem', color: '#718096', marginLeft: '0.5rem' }}>
                (Admin LINM luôn quét và xóa tất cả đơn vị)
              </span>
            </div>
          </>
        )}

        <div className={styles.filterSeparator} />
        <div className={styles.filterGroup}>
          <span className={styles.filterLabel}>Event / job</span>
          <label className={styles.voucherTypeOption} data-testid="cleanup-skip-platform-events">
            <input
              type="checkbox"
              checked={skipPlatformEvents}
              onChange={(e) => onSkipPlatformEventsChange(e.target.checked)}
            />
            Bỏ qua xóa Platform Events (accounting events)
          </label>
          <span style={{ fontSize: '0.8rem', color: '#718096', marginLeft: '0.5rem' }}>
            Giữ hàng đợi / lịch sử accounting events
          </span>
        </div>

        <div className={styles.filterSeparator} />
        <div className={styles.filterGroup}>
          <span className={styles.filterLabel}>Lịch sử CT</span>
          <label className={styles.voucherTypeOption} data-testid="cleanup-skip-document-history">
            <input
              type="checkbox"
              checked={skipDocumentHistory}
              onChange={(e) => onSkipDocumentHistoryChange(e.target.checked)}
            />
            Bỏ qua xóa lịch sử hoạt động CT và audit history
          </label>
          <span style={{ fontSize: '0.8rem', color: '#718096', marginLeft: '0.5rem' }}>
            Giữ DocumentActivityLogs + DocumentAuditEntries
          </span>
        </div>
      </div>
    </div>
  );
};
