/** FeaturePackage AllowedCompanyScopeJson — mirrors Auth CompanyScopeConfig. */

export type CompanyScopeMode = 'own' | 'listed' | 'all';

export interface CompanyScopeConfig {
  mode: CompanyScopeMode;
  /** Tenant codes (LINM, FM06) — legacy JSON key companyIds accepted on read. */
  companyCodes: string[];
}

function readScopeCodes(raw: { companyCodes?: string[]; companyIds?: string[] }): string[] {
  const fromCodes = raw.companyCodes ?? [];
  const fromLegacy = raw.companyIds ?? [];
  const merged = [...fromCodes, ...fromLegacy].map((v) => String(v).trim().toUpperCase()).filter(Boolean);
  return [...new Set(merged)];
}

export function parseCompanyScopeJson(json?: string | null): CompanyScopeConfig {
  if (!json?.trim()) return { mode: 'own', companyCodes: [] };
  try {
    const raw = JSON.parse(json) as { mode?: string; companyCodes?: string[]; companyIds?: string[] };
    const mode = (raw.mode?.trim().toLowerCase() ?? 'own') as CompanyScopeMode;
    if (mode === 'all') return { mode: 'all', companyCodes: [] };
    if (mode === 'listed') {
      return {
        mode: 'listed',
        companyCodes: readScopeCodes(raw),
      };
    }
    return { mode: 'own', companyCodes: [] };
  } catch {
    return { mode: 'own', companyCodes: [] };
  }
}

export function buildCompanyScopeJson(mode: CompanyScopeMode, companyCodes: string[]): string {
  const codes = mode === 'listed'
    ? [...new Set(companyCodes.map((code) => code.trim().toUpperCase()).filter(Boolean))]
    : [];
  return JSON.stringify({
    mode,
    companyCodes: codes,
  });
}

export function mergeAllowedCompanyCodesFromPackages(
  packages: Array<{ allowedCompanyScopeJson?: string | null }>,
  homeCompanyCode?: string | null,
): string[] {
  const codes = new Set<string>();
  let canViewAll = false;

  for (const pkg of packages) {
    const scope = parseCompanyScopeJson(pkg.allowedCompanyScopeJson);
    if (scope.mode === 'all') {
      canViewAll = true;
      break;
    }
    if (scope.mode === 'listed') {
      scope.companyCodes.forEach((code) => codes.add(code));
    }
  }

  const home = homeCompanyCode?.trim().toUpperCase();
  if (canViewAll) return home ? [home] : [];
  if (home) codes.add(home);
  return [...codes];
}

export const USER_SCOPE_PACKAGE_PREFIX = 'SCOPE-';

export function userScopePackageCode(username: string): string {
  const safe = username.replace(/[^a-zA-Z0-9_-]/g, '').toUpperCase().slice(0, 24);
  return `${USER_SCOPE_PACKAGE_PREFIX}${safe || 'USER'}`;
}
