import React from 'react';
import { useLocation } from 'react-router-dom';
import { useAppSelector } from '../../store/hooks';
import { ForbiddenPage, hasValidAuthToken } from '@linm-soft-org/linm-web-common-components';
import { useAdminPermissions } from '../../hooks/useAdminPermissions';
import { isStandalone } from '../../dev/isStandalone';
import { isAdminPermissionsBypass } from '../../dev/isAdminPermissionsBypass';
import { AuthLoginRedirect } from './AuthLoginRedirect';
import {
  hasAdminPagePermission,
  hasAnyAdminHomeAccess,
  hasAnyJobsPagePermission,
  normalizeAdminPath,
  resolveAdminPathPermission,
} from '../../config/adminPermissions';

interface ProtectedRouteProps {
  children: React.ReactNode;
}

/**
 * Route guard for admin MFE.
 *
 * Guard order:
 *  1. Not authenticated → redirect to /login
 *  2. Permissions loading → show spinner
 *  3. Path permission (Auth permissionCodes) AND menu/path grant → ForbiddenPage
 *  4. Authenticated + authorised → render children
 *
 * Identity role Admin does NOT bypass — only FeaturePackage permissionCodes + assigned menus.
 */
export const ProtectedRoute: React.FC<ProtectedRouteProps> = ({ children }) => {
  const { isAuthenticated } = useAppSelector((state) => state.auth);
  const location = useLocation();
  const { loading, hasPermission, hasMenuAccess } = useAdminPermissions();

  // 1. Not authenticated or token cleared/tampered without Redux refresh
  if (!isStandalone && (!isAuthenticated || !hasValidAuthToken())) {
    return <AuthLoginRedirect />;
  }

  // 2. Still fetching permission payload (standalone seeds full access in hook)
  if (!isAdminPermissionsBypass() && loading) {
    return (
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', minHeight: 200 }}>
        <i className="fas fa-spinner fa-spin" style={{ fontSize: 24, color: 'var(--primary-color, #2563eb)' }} />
      </div>
    );
  }

  // 3. Path gated by page permission + assigned menu path (defense in depth)
  const isAdminPath = location.pathname.startsWith('/admin');
  let accessPath = location.pathname;
  if (accessPath === '/admin/packages') accessPath = '/admin/permissions';
  else if (accessPath === '/admin/') accessPath = '/admin';

  if (isAdminPath && !isAdminPermissionsBypass()) {
    const normalized = normalizeAdminPath(accessPath);
    let allowed = false;
    if (normalized === '/admin') {
      allowed = hasAnyAdminHomeAccess(hasPermission);
    } else if (normalized === '/admin/jobs') {
      allowed = hasAnyJobsPagePermission(hasPermission);
    } else {
      const code = resolveAdminPathPermission(accessPath);
      // Unknown /admin/* path → deny (do not fall back to accounts:read).
      allowed = code ? hasAdminPagePermission(hasPermission, code) : false;
    }
    // Menu/path grant required — URL alone + leaked permissionCodes cannot open unassigned pages.
    if (allowed && !hasMenuAccess(normalized)) {
      allowed = false;
    }
    if (!allowed) return <ForbiddenPage />;
  }

  // 4. Authorised
  return <>{children}</>;
};
