import React from 'react';
import ExternalSyncRunsSplitPane from './components/ExternalSyncRunsSplitPane';
import ExternalSyncLegacyInvoicePanel from './views/ExternalSyncLegacyInvoicePanel';

const LegacyInvoiceRunsPage: React.FC = () => {
  const splitPaneRef = React.useRef<{ openRunAndScroll: (runId: string) => void }>(null);
  const postControlsRef = React.useRef<{ legacyRepostPaused?: boolean }>({});

  const handleRunStarted = React.useCallback((runId: string) => {
    splitPaneRef.current?.openRunAndScroll(runId);
  }, []);

  return (
    <ExternalSyncRunsSplitPane
      ref={splitPaneRef}
      view="legacy-invoice"
      title="Ghi sổ HĐ POS thiếu công nợ"
    >
      <ExternalSyncLegacyInvoicePanel
        legacyRepostPaused={postControlsRef.current.legacyRepostPaused}
        onRunStarted={handleRunStarted}
      />
    </ExternalSyncRunsSplitPane>
  );
};

export default LegacyInvoiceRunsPage;
